#[cfg(test)]
fn management_route_specs() -> &'static [ManagementRouteSpec] {
    MANAGEMENT_ROUTE_SPECS
}

fn management_route_spec(method: &str, path: &str) -> Option<&'static ManagementRouteSpec> {
    MANAGEMENT_ROUTE_SPECS
        .iter()
        .find(|spec| spec.method == method && spec.path == path)
}

fn is_management_path(path: &str) -> bool {
    path == "/management" || path.starts_with("/management/")
}

async fn management_role_gate(
    State(state): State<AppState>,
    request: Request,
    next: Next,
) -> Response {
    if !is_management_path(request.uri().path()) {
        return next.run(request).await;
    }

    let peer = match request.extensions().get::<ConnectInfo<SocketAddr>>() {
        Some(ConnectInfo(peer)) => peer,
        None => {
            return auth::json_error(
                StatusCode::FORBIDDEN,
                "management peer address is unavailable",
            );
        }
    };
    let peer_allowed = state
        .management_ip_allowlist
        .read()
        .expect("management IP allowlist lock poisoned")
        .allows_ip(peer.ip());
    if !peer_allowed {
        return auth::json_error(
            StatusCode::FORBIDDEN,
            "management peer address is not allowed",
        );
    }

    let principal = match authorize_management(&state, request.headers()) {
        Ok(principal) => principal,
        Err(response) => return *response,
    };
    let matched_path = request
        .extensions()
        .get::<MatchedPath>()
        .map(MatchedPath::as_str)
        .unwrap_or_else(|| request.uri().path());
    let Some(spec) = management_route_spec(request.method().as_str(), matched_path) else {
        return auth::json_error(StatusCode::FORBIDDEN, "management route is not registered");
    };
    if !principal.role.allows(spec.minimum_role) {
        return auth::json_error(
            StatusCode::FORBIDDEN,
            "management principal role is not allowed for this route",
        );
    }

    next.run(request).await
}

async fn unregistered_management_route() -> Response {
    auth::json_error(StatusCode::FORBIDDEN, "management route is not registered")
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env())
        .init();

    let args = Args::parse();
    let registry = YamlRegistryRepository::new(args.config).load_registry()?;
    let registry_startup = match std::env::var_os("KEY_POOL_ROUTER_SQLITE_REGISTRY_STORE") {
        Some(path) => SqliteRegistryStore::load_or_bootstrap_startup_document(path, registry)?,
        None => registry_store::RegistryStartupDocument {
            document: registry,
            store: RegistryStoreHandle::read_only(),
        },
    };
    let registry_document = registry_startup.document;
    let config = registry_document.clone().resolve()?;
    let listen = config.listen;
    let state = AppState::new_with_registry_store_and_validation_bootstrap(
        config,
        registry_startup.store,
        Some(registry_document),
    )?;

    let app = app(state);

    let listener = tokio::net::TcpListener::bind(listen).await?;
    tracing::info!("key-pool-router listening on {listen}");
    axum::serve(
        listener,
        app.into_make_service_with_connect_info::<SocketAddr>(),
    )
    .with_graceful_shutdown(shutdown_signal())
    .await?;

    Ok(())
}

#[cfg(not(test))]
fn app(state: AppState) -> Router {
    app_without_test_peer_default(state)
}

#[cfg(test)]
fn app(state: AppState) -> Router {
    app_without_test_peer_default(state).layer(middleware::from_fn(default_test_connect_info))
}

