    fn source_file(path: &str) -> String {
        fs::read_to_string(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(path)).unwrap()
    }

    fn production_source(path: &str) -> String {
        strip_cfg_test_items(&source_file(path))
    }

    fn retired_management_service_source() -> String {
        String::new()
    }

    fn strip_cfg_test_items(source: &str) -> String {
        let mut output = String::new();
        let mut cursor = 0;

        while let Some(relative_start) = source[cursor..].find("#[cfg(test)]") {
            let attr_start = cursor + relative_start;
            output.push_str(&source[cursor..attr_start]);

            let mut item_start = line_end(source, attr_start);
            loop {
                item_start = skip_whitespace(source, item_start);
                if source[item_start..].starts_with("#[") {
                    item_start = line_end(source, item_start);
                    continue;
                }
                break;
            }

            if source[item_start..].starts_with("mod tests")
                || source[item_start..].starts_with("pub mod tests")
            {
                cursor = source.len();
                break;
            }

            cursor = item_end(source, item_start);
        }

        output.push_str(&source[cursor..]);
        output
    }

    fn line_end(source: &str, start: usize) -> usize {
        source[start..]
            .find('\n')
            .map(|offset| start + offset + 1)
            .unwrap_or(source.len())
    }

    fn skip_whitespace(source: &str, start: usize) -> usize {
        source[start..]
            .find(|ch: char| !ch.is_whitespace())
            .map(|offset| start + offset)
            .unwrap_or(source.len())
    }

    fn item_end(source: &str, start: usize) -> usize {
        let Some(relative_open_brace) = source[start..].find('{') else {
            return line_end(source, start);
        };
        let open_brace = start + relative_open_brace;
        let semicolon = source[start..].find(';').map(|offset| start + offset);
        if semicolon.is_some_and(|semicolon| semicolon < open_brace) {
            return semicolon.unwrap() + 1;
        }

        let mut depth = 0usize;
        for (offset, ch) in source[open_brace..].char_indices() {
            match ch {
                '{' => depth += 1,
                '}' => {
                    depth -= 1;
                    if depth == 0 {
                        return open_brace + offset + ch.len_utf8();
                    }
                }
                _ => {}
            }
        }

        source.len()
    }

    #[test]
    fn production_source_preserves_items_after_inline_cfg_test_helpers() {
        let source = production_source("src/pool.rs");

        assert!(source.contains("pub fn apply_credential_cooldown_until"));
    }

    #[test]
    fn management_service_module_is_retired() {
        let main_source = source_file("src/main.rs");
        let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));

        assert!(!manifest_dir.join("src/management_service.rs").exists());
        assert!(!main_source
            .lines()
            .any(|line| line.trim() == "mod management_service;"));
        let service_path_token = ["management", "_service::"].concat();
        let crate_service_path_token = ["crate::management", "_service"].concat();
        assert!(!main_source.contains(&service_path_token));
        assert!(!main_source.contains(&crate_service_path_token));
    }

    #[test]
    fn registry_document_resolves_response_filter_policy() {
        let mut document =
            test_config_with_api_base("https://example.com/v1").into_registry_document();
        document.response_filter = crate::config::ResponseFilterConfig {
            enabled: true,
            replacement: Some("[filtered]".to_string()),
            event_window_capacity: None,
            alert_window_seconds: None,
            rules: vec![crate::config::ResponseFilterRuleConfig {
                id: "marker".to_string(),
                enabled: true,
                kind: crate::config::ResponseFilterRuleKindConfig::Literal,
                action: crate::config::ResponseFilterActionConfig::Redact,
                case_sensitive: false,
                value: Some("unsafe-marker".to_string()),
                pattern: None,
            }],
        };

        let resolved = document.resolve().unwrap();

        assert!(resolved.response_filter.is_effective());
        assert_eq!(
            resolved.response_filter.inspect_text("unsafe-marker"),
            crate::response_filter::ResponseFilterDecision::Redacted {
                text: "[filtered]".to_string(),
                matches: vec![crate::response_filter::ResponseFilterMatch {
                    rule_id: "marker".to_string(),
                    action: crate::response_filter::ResponseFilterAction::Redact,
                    reason_code: "rule_matched",
                }],
            }
        );
    }

    #[test]
    fn registry_document_rejects_duplicate_response_filter_rule_ids() {
        let mut document =
            test_config_with_api_base("https://example.com/v1").into_registry_document();
        document.response_filter = crate::config::ResponseFilterConfig {
            enabled: true,
            replacement: Some("[filtered]".to_string()),
            event_window_capacity: None,
            alert_window_seconds: None,
            rules: vec![
                crate::config::ResponseFilterRuleConfig {
                    id: "relay-ad".to_string(),
                    enabled: true,
                    kind: crate::config::ResponseFilterRuleKindConfig::Literal,
                    action: crate::config::ResponseFilterActionConfig::Redact,
                    case_sensitive: false,
                    value: Some("unsafe-marker".to_string()),
                    pattern: None,
                },
                crate::config::ResponseFilterRuleConfig {
                    id: "relay-ad".to_string(),
                    enabled: true,
                    kind: crate::config::ResponseFilterRuleKindConfig::Regex,
                    action: crate::config::ResponseFilterActionConfig::Reject,
                    case_sensitive: false,
                    value: None,
                    pattern: Some("unsafe-[a-z]+".to_string()),
                },
            ],
        };

        let err = document
            .resolve()
            .expect_err("duplicate enabled response filter rule ids must fail");

        assert!(
            err.to_string()
                .contains("duplicate response_filter rule id relay-ad"),
            "unexpected error: {err}"
        );
    }

