    #[test]
    fn registry_resolve_preserves_sqlite_credential_store_path() {
        let keys = temp_keys_file(&credential_lines(&[fixtures()
            .upstream_credentials
            .test_upstream
            .as_str()]));
        let client_token = fixture_client_token();
        let admin_token = fixture_admin_token();
        let config_path = temp_config_file(&format!(
            r#"
listen: 127.0.0.1:4104
client_tokens:
  - name: local-client
    token: {client_token}
management:
  admin_token: {admin_token}
credential_sets:
  relay-credentials:
    keys_file: {}
default_routing_profile: default-routing
routing_profiles:
  default-routing:
    key_selection: sticky_until_failure
    default_credential_cooldown_seconds: 20
    same_request_credential_retry:
      enabled: false
      max_retries: 0
    route_target_retry:
      enabled: true
pools:
  relay:
    provider_kind: openai_compatible
    api_base: https://example.test/v1
    credential_set: relay-credentials
"#,
            keys.display()
        ));
        let database_path = temp_config_file("").with_extension("sqlite");
        let sqlite_repository =
            crate::credential_repository::SqliteCredentialRepository::open(database_path.clone())
                .unwrap();

        let resolved = YamlRegistryRepository::new(config_path)
            .load_registry()
            .unwrap()
            .resolve_with_credential_repository_and_store_path(
                &sqlite_repository,
                Some(database_path.clone()),
            )
            .unwrap();

        assert_eq!(
            resolved.credential_store_path.as_deref(),
            Some(database_path.as_path())
        );
    }

