    #[test]
    fn claimed_upstream_guard_uses_channel_registry_index() {
        let source = production_source("src/state.rs");
        let registry_start = source
            .find("impl ChannelRegistry {")
            .expect("channel registry impl exists");
        let registry_end = source[registry_start..]
            .find("fn claimed_upstream_models_by_channel")
            .map(|offset| registry_start + offset)
            .expect("channel registry impl has following helper");
        let registry_impl = &source[registry_start..registry_end];
        let function_start = registry_impl
            .find("pub fn has_claimed_upstream_model")
            .expect("channel registry claimed upstream guard exists");
        let function_end = registry_impl[function_start..]
            .find("pub fn apply_failure_domain_transition")
            .map(|offset| function_start + offset)
            .expect("next channel registry method exists");
        let body = &registry_impl[function_start..function_end];

        assert!(body.contains("claimed_upstream_channels_from_snapshot"));
        assert!(!body.contains("model_routes.values()"));
        assert!(!body.contains("route.targets.iter()"));

        let helper_start = source
            .find("fn claimed_upstream_channels_from_snapshot")
            .expect("claimed upstream snapshot helper exists");
        let helper_end = source[helper_start..]
            .find("fn any_allowed_claimed_upstream_channel")
            .map(|offset| helper_start + offset)
            .expect("claimed upstream snapshot helper has following helper");
        let helper = &source[helper_start..helper_end];

        assert!(helper.contains("claimed_upstream_models"));
        assert!(!helper.contains("model_routes.values()"));
        assert!(!helper.contains("route.targets.iter()"));

        let snapshot_start = source
            .find("struct ChannelRegistrySnapshot")
            .expect("channel registry snapshot exists");
        let snapshot_end = source[snapshot_start..]
            .find("#[derive(Clone, Default)]")
            .map(|offset| snapshot_start + offset)
            .expect("snapshot struct has following item");
        let snapshot = &source[snapshot_start..snapshot_end];

        assert!(snapshot.contains("model_routes: Arc<HashMap<String, ModelRoute>>"));
        assert!(snapshot.contains("claimed_upstream_models: Arc<HashMap<String, Vec<String>>>"));
    }

