    #[test]
    fn proxy_forward_hot_path_uses_frozen_route_state() {
        let source = production_source("src/proxy.rs");
        assert!(source.contains("route_state: ChannelRouteState"));
        assert!(source.contains("route_target_index: Option<usize>"));
        assert!(source.contains("route_target_index: None"));
        assert!(source.contains("route_target_index: Some(candidate.target_index)"));
        assert!(source.contains("route_target_index: target.route_target_index"));

        for (start_marker, end_marker) in [
            (
                "async fn forward_streaming_named_pool",
                Some("\nfn bounded_request_body_stream"),
            ),
            ("async fn forward_with_pool", None),
        ] {
            let function_start = source
                .find(start_marker)
                .unwrap_or_else(|| panic!("{start_marker} exists"));
            let function_end = end_marker
                .and_then(|marker| {
                    source[function_start..]
                        .find(marker)
                        .map(|offset| function_start + offset)
                })
                .unwrap_or(source.len());
            let body = &source[function_start..function_end];

            assert!(body.contains("target"));
            assert!(body.contains(".route_state"));
            assert!(body.contains(".most_restrictive("));
            assert!(body.contains("pool_state.route_state()"));
            assert!(
                !body.contains("state.channels.channel_route_state("),
                "forward hot path must consume frozen route state instead of re-reading channel registry"
            );
        }
    }

