    #[test]
    fn management_profile_read_handlers_bypass_management_service() {
        let management_source = production_source("src/management.rs");
        let service_source = retired_management_service_source();

        for (handler, next_handler, expected_call_fragments) in [
            (
                "policy_profiles",
                "upsert_registry_policy_profile",
                &["policy_profiles_response(&state)"][..],
            ),
            (
                "policy_profile",
                "routing_profiles",
                &["policy_profile_response(&state, &id)"],
            ),
            (
                "routing_profiles",
                "upsert_registry_routing_profile",
                &["routing_profiles_response(&state)"],
            ),
            (
                "routing_profile",
                "routing_preview",
                &["routing_profile_response(&state, &id)"],
            ),
            (
                "error_rules",
                "expire_channel_credential",
                &["channel_error_rules_response(&state, &id)"],
            ),
        ] {
            let handler_start = management_source
                .find(&format!("pub async fn {handler}("))
                .unwrap_or_else(|| panic!("{handler} handler exists"));
            let handler_end = management_source[handler_start..]
                .find(&format!("\npub async fn {next_handler}"))
                .or_else(|| management_source[handler_start..].find("\n#[derive"))
                .map(|offset| handler_start + offset)
                .unwrap_or_else(|| panic!("{next_handler} follows {handler}"));
            let handler_body = &management_source[handler_start..handler_end];
            for expected_call_fragment in expected_call_fragments {
                assert!(
                    handler_body.contains(expected_call_fragment),
                    "{handler} handler must contain call fragment {expected_call_fragment}"
                );
            }
            assert!(
                !handler_body.contains("ManagementService::new"),
                "{handler} handler must not use ManagementService facade"
            );
        }

        assert!(!service_source.contains("pub async fn error_rules"));
        assert!(!service_source.contains("pub async fn list_policy_profiles"));
        assert!(!service_source.contains("pub async fn get_policy_profile"));
        assert!(!service_source.contains("pub async fn list_routing_profiles"));
        assert!(!service_source.contains("pub async fn get_routing_profile"));
    }

