        let credential_set_operations_response_body = &operations_source
            [credential_set_operations_response_start..credential_set_operations_response_end];
        assert!(credential_set_operations_response_body
            .contains("topology: &CredentialSetTopologyProjection"));
        assert!(credential_set_operations_response_body.contains("topology.channel_ids.clone()"));
        assert!(credential_set_operations_response_body.contains("topology.account_ids.clone()"));
