    #[test]
    fn management_resource_read_handlers_bypass_management_service() {
        let management_source = production_source("src/management.rs");
        let service_source = retired_management_service_source();

        for (handler, next_handler, expected_call) in [
            (
                "providers",
                "upsert_registry_provider",
                "providers_response(&state).await",
            ),
            (
                "accounts",
                "upsert_registry_account",
                "accounts_response(&state).await",
            ),
            (
                "credential_sets",
                "credential_set_operations",
                "credential_sets_response_for_state(&state).await",
            ),
            (
                "credential_set_operations",
                "list_credential_set_credentials",
                "credential_set_operations_for_set(&state, &id).await",
            ),
            (
                "alerts",
                "readiness",
                "alerts_response_for_state(&state).await",
            ),
        ] {
            let handler_start = management_source
                .find(&format!("pub async fn {handler}"))
                .unwrap_or_else(|| panic!("{handler} handler exists"));
            let handler_end = management_source[handler_start..]
                .find(&format!("\npub async fn {next_handler}"))
                .map(|offset| handler_start + offset)
                .unwrap_or_else(|| panic!("{next_handler} handler follows {handler}"));
            let handler_body = &management_source[handler_start..handler_end];
            assert!(
                handler_body.contains(expected_call),
                "{handler} handler must call {expected_call}"
            );
            assert!(
                !handler_body.contains("ManagementService::new"),
                "{handler} handler must not use ManagementService facade"
            );
        }

        assert!(!service_source.contains("pub async fn providers"));
        assert!(!service_source.contains("pub async fn accounts"));
        assert!(!service_source.contains("pub async fn credential_sets"));
        assert!(!service_source.contains("pub async fn credential_set_operations"));
        assert!(!service_source.contains("pub async fn alerts"));
    }

