    fn credential_set_channel_lookup_uses_registry_index() {
        let main_source = production_source("src/main.rs");
        let service_source = retired_management_service_source();
        let credential_source = production_source("src/management_credentials.rs");
        let lookup_source = production_source("src/management_resource_lookup.rs");
        let command_source = production_source("src/management_commands.rs");
        let operations_source = production_source("src/management_operations.rs");
        let resource_source = production_source("src/management_resources.rs");
        let channel_ids_start = lookup_source
            .find("pub fn channel_ids_for_credential_set")
            .expect("credential-set channel lookup exists");
        let lookup_end = lookup_source[channel_ids_start..]
            .find("pub struct CredentialSetRuntimeScope")
            .map(|offset| channel_ids_start + offset)
            .expect("next resource item exists");
        let lookup_body = &lookup_source[channel_ids_start..lookup_end];

        assert!(main_source.contains("mod management_resource_lookup;"));
        assert!(lookup_source.contains("pub fn channel_ids_for_credential_set"));
        assert!(lookup_source.contains("pub struct CredentialSetRuntimeScope"));
        assert!(lookup_source.contains("pub fn credential_set_runtime_scope"));
        assert!(lookup_body.contains(".channel_ids_for_credential_set"));
        let scope_start = lookup_source
            .find("pub fn credential_set_runtime_scope")
            .expect("credential-set runtime scope lookup exists");
        let scope_end = lookup_source[scope_start..]
            .find("pub fn ensure_credential_set_exists")
            .map(|offset| scope_start + offset)
            .expect("next credential-set lookup exists");
        let scope_body = &lookup_source[scope_start..scope_end];
        assert!(scope_body.contains("channel_pool_for_id(state, &canonical_channel_id)?"));
        assert!(!scope_body.contains(".channels.get(&canonical_channel_id)"));
        assert!(
            credential_source.contains("credential_set_runtime_scope(state, credential_set_id)?")
        );
        assert!(!credential_source.contains("canonical_pool_for_credential_set("));
        assert!(!credential_source.contains("canonical_channel_pool_for_credential_set"));
        assert!(!lookup_source.contains("pub fn canonical_channel_for_credential_set"));
        assert!(!lookup_source.contains("pub fn canonical_channel_pool_for_credential_set"));
        assert!(command_source.contains("credential_set_runtime_scope(state, credential_set_id)?"));
        assert!(command_source.contains("credential_set_command("));
        assert!(command_source.contains("CredentialCommandScope::CredentialSet"));
        assert!(resource_source.contains("channel_pool_for_id(state, channel_id)?"));
        assert!(
            operations_source.contains("credential_set_runtime_scope(state, credential_set_id)?")
        );
        for token in [
            "pub fn channel_pool_for_id",
            "pub fn channel_ids_for_credential_set",
            "pub fn ensure_credential_set_exists",
            "pub fn credential_set_runtime_scope",
        ] {
            assert!(
                !resource_source.contains(token),
                "management resources must not own credential lookup helper {token}"
            );
        }
        assert!(!service_source.contains("fn canonical_channel_for_credential_set"));
        assert!(!service_source.contains("fn channel_ids_for_credential_set"));
        assert!(!lookup_body.contains("state.channels.iter()"));
        assert!(!lookup_body.contains("pool_state.credential_set_id.0 == credential_set_id"));
    }

