    #[tokio::test]
    async fn ready_route_returns_service_unavailable_when_credentials_are_exhausted() {
        let state = test_state();
        let credential_id = {
            let channel = state.channels.get("test").unwrap();
            let pool = channel.pool.lock().await;
            pool.credential_snapshots()[0].id.clone()
        };
        {
            let channel = state.channels.get("test").unwrap();
            channel
                .pool
                .lock()
                .await
                .expire_credential_by_id(
                    &crate::credentials::CredentialId(credential_id),
                    "upstream auth invalid",
                )
                .unwrap();
        }

        let response = app(state.clone())
            .oneshot(
                Request::builder()
                    .uri("/ready")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::SERVICE_UNAVAILABLE);
        let value = response_json(response).await;
        assert_eq!(value["status"], "not_ready");
        assert_eq!(value["serving_channels"], 0);
        assert_eq!(value["credentials"]["available"], 0);
        assert_eq!(value["blocking_alerts"], 1);
    }

    #[tokio::test]
    async fn ready_route_treats_active_channel_cooldown_as_not_ready() {
        let state = test_state();
        {
            let channel = state.channels.get("test").unwrap();
            *channel.health.lock().unwrap() = ChannelHealth::CoolingDown {
                until: Instant::now() + Duration::from_secs(30),
                reason: "provider cooldown".to_string(),
            };
        }

        let response = app(state.clone())
            .oneshot(
                Request::builder()
                    .uri("/ready")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::SERVICE_UNAVAILABLE);
        let value = response_json(response).await;
        assert_eq!(value["status"], "not_ready");
        assert_eq!(value["serving_channels"], 0);
        assert_eq!(value["channels"], 1);
        assert_eq!(value["credentials"]["available"], 1);
    }

