    async fn management_response_json(app: &Router, uri: &str) -> Value {
        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(uri)
                    .header(header::AUTHORIZATION, admin_bearer())
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = to_bytes(response.into_body(), 8192).await.unwrap();
        serde_json::from_slice::<Value>(&body).unwrap()
    }

    async fn response_json(response: Response) -> Value {
        let body = to_bytes(response.into_body(), 8192).await.unwrap();
        serde_json::from_slice::<Value>(&body).unwrap()
    }

    fn assert_management_event(
        events: &Value,
        index: usize,
        kind: &str,
        resource_type: &str,
        resource_id: &str,
        generation: u64,
        reason_code: &str,
    ) {
        let event = &events["events"][index];
        assert_eq!(event["kind"], kind);
        assert_eq!(event["action"], kind);
        assert_eq!(event["resource_type"], resource_type);
        assert_eq!(event["resource_id"], resource_id);
        assert_eq!(event["outcome"], "applied");
        assert_eq!(event["generation"], generation);
        assert_eq!(event["reason_code"], reason_code);
    }

    fn registry_provider_fixture() -> (Router, PathBuf) {
        registry_provider_fixture_with_channel_enabled(true)
    }

    fn registry_provider_fixture_with_event_log_path(event_log_path: PathBuf) -> (Router, PathBuf) {
        registry_provider_fixture_with_channel_enabled_and_event_log_path(
            true,
            Some(event_log_path),
        )
    }

    fn registry_provider_fixture_with_channel_enabled(channel_enabled: bool) -> (Router, PathBuf) {
        registry_provider_fixture_with_channel_enabled_and_event_log_path(channel_enabled, None)
    }

    fn registry_provider_fixture_with_channel_enabled_and_event_log_path(
        channel_enabled: bool,
        event_log_path: Option<PathBuf>,
    ) -> (Router, PathBuf) {
        let keys_file = temp_keys_file("upstream-key\n");
        let credential_store_path = temp_sqlite_path("registry-provider-credentials");
        let registry_store_path = temp_sqlite_path("registry-provider");
        let registry: RegistryDocument = AppConfig {
            listen: "127.0.0.1:0".parse().unwrap(),
            client_tokens: vec![ClientTokenConfig {
                name: "test-client".to_string(),
                token: fixture_client_token(),
                enabled: true,
                allowed_model_groups: Vec::new(),
                allowed_channels: Vec::new(),
            }],
            management: Some(ManagementConfig {
                admin_token: fixture_admin_token(),
                ip_allowlist: None,
                principals: Vec::new(),
                event_log_path,
                event_window_capacity: None,
            }),
            max_request_body_bytes: 1024 * 1024,
            max_model_catalog_body_bytes: 512 * 1024,
            max_error_body_bytes: 1024,
            timeouts: TimeoutConfig::default(),
            routing: crate::config::RoutingConfig::default(),
            default_pool: Some("test".to_string()),
            providers: HashMap::from([(
                "relay".to_string(),
                crate::config::ProviderConfig {
                    provider_kind: ProviderKind::OpenAiCompatible,
                    enabled: true,
                },
            )]),
            accounts: HashMap::from([(
                "relay-account".to_string(),
                crate::config::AccountConfig {
                    provider: "relay".to_string(),
                    api_base: "https://example.com/v1".to_string(),
                    auth_header: "Authorization".to_string(),
                    auth_prefix: "Bearer ".to_string(),
                    enabled: true,
                },
            )]),
            credential_sets: credential_sets_from_files([("test-credentials", keys_file)]),
            model_routes: HashMap::new(),
            policy_profiles: HashMap::new(),
            default_routing_profile: Some("default-routing".to_string()),
            routing_profiles: HashMap::from([(
                "default-routing".to_string(),
                crate::config::RoutingProfileConfig {
                    key_selection: crate::config::KeySelectionStrategyConfig::StickyUntilFailure,
                    default_credential_cooldown_seconds: 20,
                    same_request_credential_retry:
                        crate::config::SameRequestCredentialRetryConfig {
                            enabled: false,
                            max_retries: 0,
                        },
                    route_target_retry: crate::config::RouteTargetRetryConfig { enabled: true },
                },
            )]),
            pools: HashMap::from([(
                "test".to_string(),
                PoolConfig {
                    enabled: channel_enabled,
                    account: Some("relay-account".to_string()),
                    policy_profile: None,
                    routing_profile: Some("default-routing".to_string()),
                    provider_kind: ProviderKind::OpenAiCompatible,
                    api_base: "https://legacy.example.test/v1".to_string(),
                    credential_set: "test-credentials".to_string(),
                    auth_header: "Authorization".to_string(),
                    auth_prefix: "Bearer ".to_string(),
                    error_rules: Default::default(),
                },
            )]),
        }
        .into_registry_document();
        SqliteRegistryStore::bootstrap_from_document(&registry_store_path, registry.clone())
            .unwrap();
        let repository = SqliteCredentialRepository::open(&credential_store_path).unwrap();
        let config = registry
            .clone()
            .resolve_with_credential_repository_and_store_path(
                &repository,
                Some(credential_store_path),
            )
            .unwrap();
        let state = AppState::new_with_registry_store_and_validation_bootstrap(
            config,
            RegistryStoreHandle::sqlite(&registry_store_path).unwrap(),
            Some(registry.clone()),
        )
        .unwrap();
        (app(state), registry_store_path)
    }

    #[tokio::test]
    async fn management_registry_provider_disable_persists_without_hot_reload() {
        let (app, registry_store_path) = registry_provider_fixture();

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/management/registry/providers/relay/disable")
                    .header(header::AUTHORIZATION, admin_bearer())
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::OK);
        let body = to_bytes(response.into_body(), 4096).await.unwrap();
        let body = serde_json::from_slice::<Value>(&body).unwrap();
        assert_eq!(body["provider_id"], "relay");
        assert_eq!(body["enabled"], false);
        assert_eq!(body["registry_version"], 2);
        assert_eq!(body["staged_registry_version"], 2);
        let active_registry_generation = body["active_registry_generation"].as_u64().unwrap();
        assert!(active_registry_generation > 0);
        assert_eq!(body["applied_to_runtime"], false);
        assert_eq!(body["runtime_reload_required"], true);

        let events = management_response_json(&app, "/management/events").await;
        assert_eq!(events["events"][0]["kind"], "registry_provider_disabled");
        assert_eq!(events["events"][0]["action"], "registry_provider_disabled");
        assert_eq!(events["events"][0]["resource_type"], "registry_provider");
        assert_eq!(events["events"][0]["resource_id"], "relay");
        assert_eq!(events["events"][0]["outcome"], "applied");
        assert_eq!(events["events"][0]["generation"], 2);
        assert_eq!(
            events["events"][0]["reason_code"],
            "manual_registry_provider_disable"
        );
        assert_eq!(events["events"][0]["actor"]["role"], "admin");

        let stored = SqliteRegistryStore::open(&registry_store_path)
            .unwrap()
            .load_registry_for_validation()
            .unwrap();
        assert!(!stored.providers["relay"].enabled);

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/management/registry/providers/relay/enable")
                    .header(header::AUTHORIZATION, admin_bearer())
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::OK);
        let body = to_bytes(response.into_body(), 4096).await.unwrap();
        let body = serde_json::from_slice::<Value>(&body).unwrap();
        assert_eq!(body["provider_id"], "relay");
        assert_eq!(body["enabled"], true);
        assert_eq!(body["registry_version"], 3);
        assert_eq!(body["staged_registry_version"], 3);
        assert_eq!(
            body["active_registry_generation"].as_u64().unwrap(),
            active_registry_generation
        );
        assert_eq!(body["applied_to_runtime"], false);
        assert_eq!(body["runtime_reload_required"], true);

        let events = management_response_json(&app, "/management/events").await;
        assert_eq!(events["events"][1]["kind"], "registry_provider_enabled");
        assert_eq!(events["events"][1]["resource_type"], "registry_provider");
        assert_eq!(events["events"][1]["resource_id"], "relay");
        assert_eq!(events["events"][1]["generation"], 3);
        assert_eq!(
            events["events"][1]["reason_code"],
            "manual_registry_provider_enable"
        );

        let stored = SqliteRegistryStore::open(&registry_store_path)
            .unwrap()
            .load_registry_for_validation()
            .unwrap();
        assert!(stored.providers["relay"].enabled);

        let providers = management_response_json(&app, "/management/providers").await;
        assert_eq!(providers["providers"][0]["enabled"], true);
    }

    #[tokio::test]
    async fn management_runtime_reports_staged_registry_version() {
        let (app, _) = registry_provider_fixture();
        let before = management_response_json(&app, "/management/runtime").await;
        let active_registry_generation = before["active_registry_generation"].as_u64().unwrap();
        assert!(active_registry_generation > 0);
        assert_eq!(before["active_registry_version"], 1);
        assert_eq!(before["staged_registry_version"], 1);
        assert_eq!(before["runtime_reload_required"], false);

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/management/registry/providers/relay/disable")
                    .header(header::AUTHORIZATION, admin_bearer())
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);

        let after = management_response_json(&app, "/management/runtime").await;
        assert_eq!(
            after["active_registry_generation"],
            active_registry_generation
        );
        assert_eq!(after["active_registry_version"], 1);
        assert_eq!(after["staged_registry_version"], 2);
        assert_eq!(after["runtime_reload_required"], true);
    }

    #[tokio::test]
    async fn management_runtime_reload_applies_staged_registry_snapshot() {
        let (app, _) = registry_provider_fixture();
        let before = management_response_json(&app, "/management/runtime").await;
        let active_registry_generation = before["active_registry_generation"].as_u64().unwrap();
        assert_eq!(before["active_registry_version"], 1);
        assert_eq!(before["staged_registry_version"], 1);
        assert_eq!(before["runtime_reload_required"], false);

        let disable = app
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/management/registry/providers/relay/disable")
                    .header(header::AUTHORIZATION, admin_bearer())
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(disable.status(), StatusCode::OK);

        let staged = management_response_json(&app, "/management/runtime").await;
        assert_eq!(staged["active_registry_version"], 1);
        assert_eq!(staged["staged_registry_version"], 2);
        assert_eq!(staged["runtime_reload_required"], true);

        let reload = app
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/management/runtime/reload")
                    .header(header::AUTHORIZATION, admin_bearer())
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(reload.status(), StatusCode::OK);
        let body = to_bytes(reload.into_body(), 4096).await.unwrap();
        let body = serde_json::from_slice::<Value>(&body).unwrap();
        assert!(body["active_registry_generation"].as_u64().unwrap() > active_registry_generation);
        assert_eq!(body["active_registry_version"], 2);
        assert_eq!(body["staged_registry_version"], 2);
        assert_eq!(body["runtime_reload_required"], false);

        let after = management_response_json(&app, "/management/runtime").await;
        assert_eq!(after["active_registry_version"], 2);
        assert_eq!(after["staged_registry_version"], 2);
        assert_eq!(after["runtime_reload_required"], false);

        let providers = management_response_json(&app, "/management/providers").await;
        assert_eq!(providers["providers"][0]["enabled"], false);

        let events = management_response_json(&app, "/management/events").await;
        assert_eq!(events["events"][1]["kind"], "runtime_reloaded");
        assert_eq!(events["events"][1]["action"], "runtime_reloaded");
        assert_eq!(events["events"][1]["resource_type"], "runtime");
        assert_eq!(events["events"][1]["resource_id"], "runtime");
        assert_eq!(events["events"][1]["outcome"], "applied");
        assert_eq!(events["events"][1]["generation"], 2);
        assert_eq!(events["events"][1]["reason_code"], "manual_runtime_reload");
        assert_eq!(events["events"][1]["actor"]["name"], "local-admin");
        assert_eq!(events["events"][1]["actor"]["role"], "admin");
    }

