    #[tokio::test]
    async fn management_registry_routing_profile_upsert_persists_without_hot_reload() {
        let (app, registry_store_path) = registry_provider_fixture();

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .method("PUT")
                    .uri("/management/registry/routing-profiles/default-routing")
                    .header(header::AUTHORIZATION, admin_bearer())
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{
                            "key_selection":"sticky_until_failure",
                            "default_credential_cooldown_seconds":45,
                            "same_request_credential_retry":{"enabled":true,"max_retries":2},
                            "route_target_retry":{"enabled":false}
                        }"#,
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::OK);
        let body = to_bytes(response.into_body(), 4096).await.unwrap();
        let body = serde_json::from_slice::<Value>(&body).unwrap();
        assert_eq!(body["profile_id"], "default-routing");
        assert_eq!(body["registry_version"], 2);
        assert_eq!(body["applied_to_runtime"], false);
        assert_eq!(body["runtime_reload_required"], true);

        let events = management_response_json(&app, "/management/events").await;
        assert_management_event(
            &events,
            0,
            "registry_routing_profile_upserted",
            "registry_routing_profile",
            "default-routing",
            2,
            "manual_registry_routing_profile_upsert",
        );

        let stored = SqliteRegistryStore::open(&registry_store_path)
            .unwrap()
            .load_registry_for_validation()
            .unwrap();
        assert_eq!(
            stored.routing_profiles["default-routing"].default_credential_cooldown_seconds,
            45
        );
        assert_eq!(
            stored.routing_profiles["default-routing"]
                .same_request_credential_retry
                .max_retries,
            2
        );

        let runtime_profiles = management_response_json(&app, "/management/routing-profiles").await;
        assert_eq!(
            runtime_profiles["routing_profiles"][0]["default_credential_cooldown_seconds"],
            20
        );
        assert_eq!(
            runtime_profiles["routing_profiles"][0]["same_request_credential_retry_enabled"],
            false
        );
    }

