    #[tokio::test]
    async fn management_can_update_client_token_scope_without_restart() {
        let upstream = Router::new().route(
            "/v1/chat/completions",
            post(|| async { Json(serde_json::json!({"id":"ok"})) }),
        );
        let api_base = spawn_upstream(upstream).await;
        let state = test_state_with_api_base(&api_base);
        let app = app(state);

        let create = app
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/management/client-tokens")
                    .header(header::AUTHORIZATION, admin_bearer())
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        serde_json::json!({
                            "name": "scoped-client",
                            "token": fixture_scoped_client_token(),
                            "allowed_model_groups": ["gpt-before"],
                            "allowed_channels": ["test"]
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(create.status(), StatusCode::CREATED);
        let create_body = to_bytes(create.into_body(), 4096).await.unwrap();
        let created = serde_json::from_slice::<Value>(&create_body).unwrap();
        let token_id = created["token"]["id"].as_str().unwrap();

        let rejected_before_update = app
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/chat/completions")
                    .header(
                        header::AUTHORIZATION,
                        bearer_for(fixture_scoped_client_token().as_str()),
                    )
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-after","messages":[{"role":"user","content":"ok"}]}"#,
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(rejected_before_update.status(), StatusCode::FORBIDDEN);

        let update = app
            .clone()
            .oneshot(
                Request::builder()
                    .method("PATCH")
                    .uri(format!("/management/client-tokens/{token_id}"))
                    .header(header::AUTHORIZATION, admin_bearer())
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"allowed_model_groups":["gpt-after"],"allowed_channels":["test"]}"#,
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(update.status(), StatusCode::OK);
        let update_body = to_bytes(update.into_body(), 4096).await.unwrap();
        let updated = serde_json::from_slice::<Value>(&update_body).unwrap();
        assert_eq!(updated["token"]["allowed_model_groups"][0], "gpt-after");
        assert_eq!(updated["token"]["allowed_channels"][0], "test");

        let events = management_response_json(&app, "/management/events").await;
        assert_eq!(events["events"][0]["kind"], "client_token_created");
        assert_eq!(events["events"][1]["kind"], "client_token_scope_updated");
        assert_eq!(events["events"][1]["resource_type"], "client_token");
        assert_eq!(events["events"][1]["resource_id"], token_id);
        assert_eq!(
            events["events"][1]["reason_code"],
            "manual_client_token_scope_update"
        );
        assert!(!events
            .to_string()
            .contains(fixture_scoped_client_token().as_str()));

        let rejected_old_scope = app
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/chat/completions")
                    .header(
                        header::AUTHORIZATION,
                        bearer_for(fixture_scoped_client_token().as_str()),
                    )
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-before","messages":[{"role":"user","content":"ok"}]}"#,
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(rejected_old_scope.status(), StatusCode::FORBIDDEN);

        let forwarded_new_scope = app
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/chat/completions")
                    .header(
                        header::AUTHORIZATION,
                        bearer_for(fixture_scoped_client_token().as_str()),
                    )
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-after","messages":[{"role":"user","content":"ok"}]}"#,
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(forwarded_new_scope.status(), StatusCode::OK);
    }

