    #[tokio::test]
    async fn management_client_token_store_does_not_persist_plaintext_secret() {
        let stored_client_token = fixture_persisted_client_token();
        let store_path = temp_sqlite_path("client-token-redaction");
        let state = test_state_with_keys_api_base_event_log_and_store_path(
            "upstream-key\n",
            "https://example.com/v1",
            None,
            store_path.clone(),
        );
        let response = app(state.clone())
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/management/client-tokens")
                    .header(header::AUTHORIZATION, admin_bearer())
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        serde_json::json!({
                            "name": "stored-client",
                            "token": stored_client_token.as_str()
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::CREATED);

        let connection = rusqlite::Connection::open(store_path).unwrap();
        let stored_hash: String = connection
            .query_row(
                "SELECT token_hash FROM client_tokens WHERE name = ?1",
                rusqlite::params!["stored-client"],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(stored_hash, hash_token(&stored_client_token));
        let plaintext_count: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM client_tokens WHERE token_hash = ?1",
                rusqlite::params![stored_client_token],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(plaintext_count, 0);
    }

