    #[tokio::test]
    async fn management_provider_and_account_status_are_redacted() {
        let keys_file_a = temp_keys_file("upstream-key-a\n");
        let keys_file_b = temp_keys_file("upstream-key-b\n");
        let keys_file_a_display = keys_file_a.display().to_string();
        let keys_file_b_display = keys_file_b.display().to_string();
        let mut pools = HashMap::new();
        let mut credential_sets = HashMap::new();
        for (name, keys_file, api_base) in [
            ("a", keys_file_a, "https://a.example/v1?token=hidden"),
            ("b", keys_file_b, "https://b.example/v1"),
        ] {
            let credential_set = format!("{name}-credentials");
            credential_sets.insert(
                credential_set.clone(),
                CredentialSetConfig {
                    keys_file: keys_file.clone(),
                },
            );
            pools.insert(
                name.to_string(),
                PoolConfig {
                    enabled: true,
                    account: None,
                    policy_profile: None,
                    routing_profile: None,
                    provider_kind: ProviderKind::OpenAiCompatible,
                    api_base: api_base.to_string(),
                    credential_set,
                    auth_header: "authorization".to_string(),
                    auth_prefix: "Bearer ".to_string(),
                    error_rules: ErrorRulesConfig::default(),
                },
            );
        }
        let config = AppConfig {
            listen: "127.0.0.1:0".parse().unwrap(),
            client_tokens: vec![ClientTokenConfig {
                name: "test-client".to_string(),
                token: fixture_client_token(),
                enabled: true,
                allowed_model_groups: Vec::new(),
                allowed_channels: Vec::new(),
            }],
            management: Some(ManagementConfig {
                admin_token: fixture_admin_token(),
                ip_allowlist: None,
                principals: Vec::new(),
                event_log_path: None,
                event_window_capacity: None,
            }),
            max_request_body_bytes: 1024 * 1024,
            max_model_catalog_body_bytes: 512 * 1024,
            max_error_body_bytes: 1024,
            timeouts: TimeoutConfig::default(),
            routing: crate::config::RoutingConfig::default(),
            default_pool: Some("a".to_string()),
            providers: HashMap::new(),
            accounts: HashMap::new(),
            credential_sets,
            model_routes: HashMap::new(),
            policy_profiles: HashMap::new(),
            default_routing_profile: Some("default-routing".to_string()),
            routing_profiles: std::collections::HashMap::from([(
                "default-routing".to_string(),
                crate::config::RoutingProfileConfig {
                    key_selection: crate::config::KeySelectionStrategyConfig::StickyUntilFailure,
                    default_credential_cooldown_seconds: 20,
                    same_request_credential_retry:
                        crate::config::SameRequestCredentialRetryConfig {
                            enabled: false,
                            max_retries: 0,
                        },
                    route_target_retry: crate::config::RouteTargetRetryConfig { enabled: true },
                },
            )]),
            pools,
        }
        .resolve()
        .unwrap();
        let state = AppState::new(config).unwrap();
        {
            let channel = state.channels.get("b").unwrap();
            *channel.health.lock().unwrap() = ChannelHealth::CoolingDown {
                until: Instant::now() + Duration::from_secs(60),
                reason: "provider fixture".to_string(),
            };
        }
        let app = app(state);

        let providers_response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/management/providers")
                    .header(header::AUTHORIZATION, admin_bearer())
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(providers_response.status(), StatusCode::OK);
        let providers_body = to_bytes(providers_response.into_body(), 4096)
            .await
            .unwrap();
        let providers_body = String::from_utf8(providers_body.to_vec()).unwrap();
        assert!(!providers_body.contains("upstream-key"));
        assert!(!providers_body.contains(fixture_admin_token().as_str()));
        assert!(!providers_body.contains("token_hash"));
        assert!(!providers_body.contains(&keys_file_a_display));
        assert!(!providers_body.contains(&keys_file_b_display));
        assert!(!providers_body.contains("hidden"));
        let providers = serde_json::from_str::<Value>(&providers_body).unwrap();
        assert_eq!(providers["providers"].as_array().unwrap().len(), 1);
        let provider = &providers["providers"][0];
        assert_eq!(provider["id"], "provider:openai_compatible");
        assert_eq!(provider["provider_kind"], "openai_compatible");
        assert_eq!(provider["enabled"], true);
        assert_eq!(provider["channels"], 2);
        assert_eq!(provider["channel_health"]["total"], 2);
        assert_eq!(provider["channel_health"]["available"], 1);
        assert_eq!(provider["channel_health"]["cooling_down"], 1);
        assert_eq!(provider["channel_health"]["degraded"], 0);
        assert_eq!(provider["accounts"], 2);
        assert_eq!(provider["credentials"]["total"], 2);

        let accounts_response = app
            .oneshot(
                Request::builder()
                    .uri("/management/accounts")
                    .header(header::AUTHORIZATION, admin_bearer())
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(accounts_response.status(), StatusCode::OK);
        let accounts_body = to_bytes(accounts_response.into_body(), 4096).await.unwrap();
        let accounts_body = String::from_utf8(accounts_body.to_vec()).unwrap();
        assert!(!accounts_body.contains("upstream-key"));
        assert!(!accounts_body.contains(fixture_admin_token().as_str()));
        assert!(!accounts_body.contains("token_hash"));
        assert!(!accounts_body.contains(&keys_file_a_display));
        assert!(!accounts_body.contains(&keys_file_b_display));
        assert!(!accounts_body.contains("hidden"));
        let accounts = serde_json::from_str::<Value>(&accounts_body).unwrap();
        let account_items = accounts["accounts"].as_array().unwrap();
        assert_eq!(account_items.len(), 2);
        assert_eq!(account_items[0]["id"], "account:a");
        assert_eq!(
            account_items[0]["provider_id"],
            "provider:openai_compatible"
        );
        assert_eq!(account_items[0]["channels"], 1);
        assert_eq!(account_items[0]["channel_ids"], serde_json::json!(["a"]));
        assert_eq!(
            account_items[0]["credential_set_ids"],
            serde_json::json!(["a-credentials"])
        );
        assert_eq!(account_items[0]["enabled"], true);
        assert_eq!(account_items[0]["credentials"]["total"], 1);
        assert!(account_items[0]["credential_sources"][0]["source_id"]
            .as_str()
            .unwrap()
            .contains("key-pool-router-main-test"));
    }

