        assert_eq!(discovered["models"], serde_json::json!([]));
        assert_eq!(discovered["error"]["kind"], "client_error");
        assert_eq!(discovered["error"]["scope"], "provider_adapter");
        assert_eq!(discovered["error"]["retryable"], false);
