    #[tokio::test]
    async fn management_probe_generic_credential_records_unsupported_model_without_upstream_call() {
        let upstream_hits = Arc::new(AtomicU64::new(0));
        let upstream_hits_for_handler = upstream_hits.clone();
        let upstream = spawn_upstream(Router::new().fallback(move || {
            let upstream_hits = upstream_hits_for_handler.clone();
            async move {
                upstream_hits.fetch_add(1, Ordering::SeqCst);
                StatusCode::OK
            }
        }))
        .await;
        let keys_file = temp_keys_file("generic-key-a\n");
        let db_path = temp_sqlite_path("credential-probe-generic-unsupported");
        let repository = SqliteCredentialRepository::open(&db_path).unwrap();
        let app = app(AppState::new(
            AppConfig {
                listen: "127.0.0.1:0".parse().unwrap(),
                client_tokens: vec![ClientTokenConfig {
                    name: "test-client".to_string(),
                    token: fixture_client_token(),
                    enabled: true,
                    allowed_model_groups: Vec::new(),
                    allowed_channels: Vec::new(),
                }],
                management: Some(ManagementConfig {
                    admin_token: fixture_admin_token(),
                    ip_allowlist: None,
                    principals: Vec::new(),
                    event_log_path: None,
                    event_window_capacity: None,
                }),
                max_request_body_bytes: 1024 * 1024,
                max_model_catalog_body_bytes: 512 * 1024,
                max_error_body_bytes: 1024,
                timeouts: TimeoutConfig::default(),
                routing: crate::config::RoutingConfig::default(),
                default_pool: Some("generic".to_string()),
                providers: HashMap::new(),
                accounts: HashMap::new(),
                credential_sets: credential_sets_from_files([("generic-credentials", keys_file)]),
                model_routes: HashMap::new(),
                policy_profiles: HashMap::new(),
                default_routing_profile: Some("default-routing".to_string()),
                routing_profiles: std::collections::HashMap::from([(
                    "default-routing".to_string(),
                    crate::config::RoutingProfileConfig {
                        key_selection:
                            crate::config::KeySelectionStrategyConfig::StickyUntilFailure,
                        default_credential_cooldown_seconds: 20,
                        same_request_credential_retry:
                            crate::config::SameRequestCredentialRetryConfig {
                                enabled: false,
                                max_retries: 0,
                            },
                        route_target_retry: crate::config::RouteTargetRetryConfig { enabled: true },
                    },
                )]),
                pools: HashMap::from([(
                    "generic".to_string(),
                    generic_pool(&upstream, "generic-credentials"),
                )]),
            }
            .resolve_with_credential_repository_and_store_path(&repository, Some(db_path.clone()))
            .unwrap(),
        )
        .unwrap());
        let credentials = management_response_json(
            &app,
            "/management/credential-sets/generic-credentials/credentials",
        )
        .await;
        let credential_id = credentials["credentials"][0]["id"].as_str().unwrap();

        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(format!(
                        "/management/credential-sets/generic-credentials/credentials/{credential_id}/probe"
                    ))
                    .header(header::AUTHORIZATION, admin_bearer())
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(r#"{"model":"probe-model","timeout_seconds":2}"#))
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(upstream_hits.load(Ordering::SeqCst), 0);
        let body = to_bytes(response.into_body(), 8192).await.unwrap();
        let body = String::from_utf8(body.to_vec()).unwrap();
        assert!(!body.contains("generic-key-a"));
        assert!(!body.contains(fixture_admin_token().as_str()));
        let probe = serde_json::from_str::<Value>(&body).unwrap();
        assert_eq!(probe["result"]["outcome"], "unsupported_model");
        assert_eq!(probe["result"]["provider_id"], "provider:generic_http");
        assert_eq!(probe["result"]["account_id"], "account:generic");
        assert!(probe["result"]["upstream_status"].is_null());
        assert!(probe["result"]["upstream_code"].is_null());
        assert_eq!(probe["credential"]["state"]["kind"], "available");

        let probes = management_response_json(
            &app,
            &format!(
                "/management/credential-sets/generic-credentials/credentials/{credential_id}/probes"
            ),
        )
        .await;
        assert_eq!(probes["probes"].as_array().unwrap().len(), 1);
        assert_eq!(probes["probes"][0]["outcome"], "unsupported_model");
        assert!(!probes.to_string().contains("generic-key-a"));
    }

