    #[tokio::test]
    async fn management_expire_rejects_disabled_credential() {
        let state = test_state_with_api_base("https://example.com/v1");
        let pool_state = state.channels.get("test").unwrap().clone();
        let credential_id = {
            let pool = pool_state.pool.lock().await;
            pool.credential_snapshots()[0].id.clone()
        };
        let actor = ManagementEventActor {
            id: "admin".to_string(),
            name: "local-admin".to_string(),
            role: "admin".to_string(),
        };
        disable_credential_response_for_channel(
            &state,
            actor.clone(),
            "test",
            crate::credentials::CredentialId(credential_id.clone()),
            "manual disable".to_string(),
        )
        .await
        .unwrap();

        let result = expire_credential_response_for_channel(
            &state,
            actor,
            "test",
            crate::credentials::CredentialId(credential_id.clone()),
            "manual expire".to_string(),
        )
        .await;

        assert!(matches!(
            result,
            Err(crate::management_errors::ManagementServiceError::Conflict(
                _
            ))
        ));
        let pool = pool_state.pool.lock().await;
        let snapshot = pool
            .credential_snapshot_by_id(&crate::credentials::CredentialId(credential_id))
            .unwrap();
        assert_eq!(
            snapshot.state,
            crate::credentials::CredentialStateSnapshot::Disabled {
                reason: "manual disable".to_string()
            }
        );
    }

    #[tokio::test]
    async fn management_restore_rejects_cooling_down_credential() {
        let state = test_state_with_api_base("https://example.com/v1");
        let pool_state = state.channels.get("test").unwrap().clone();
        let credential_id = {
            let mut pool = pool_state.pool.lock().await;
            let credential_id = pool.credential_snapshots()[0].id.clone();
            pool.apply_credential_cooldown_until(
                &crate::credentials::CredentialId(credential_id.clone()),
                Instant::now() + Duration::from_secs(60),
                "setup cooldown",
            );
            credential_id
        };
        let actor = ManagementEventActor {
            id: "admin".to_string(),
            name: "local-admin".to_string(),
            role: "admin".to_string(),
        };

        let result = restore_credential_response_for_channel(
            &state,
            actor,
            "test",
            crate::credentials::CredentialId(credential_id),
            "manual restore".to_string(),
        )
        .await;

        assert!(matches!(
            result,
            Err(crate::management_errors::ManagementServiceError::Conflict(
                _
            ))
        ));
        assert_eq!(state.events.len(), 0);
    }

