    #[tokio::test]
    async fn management_channels_endpoints_are_redacted() {
        let (channels_status, channels_body) =
            management_response("/management/channels", Some(admin_bearer())).await;
        assert_eq!(channels_status, StatusCode::OK);
        assert!(!channels_body.contains("upstream-key"));
        assert!(channels_body.contains("key_import"));

        let (channel_status, channel_body) =
            management_response("/management/channels/test", Some(admin_bearer())).await;
        assert_eq!(channel_status, StatusCode::OK);
        assert!(!channel_body.contains("upstream-key"));

        let (credentials_status, credentials_body) = management_response(
            "/management/channels/test/credentials",
            Some(admin_bearer()),
        )
        .await;
        assert_eq!(credentials_status, StatusCode::OK);
        assert!(!credentials_body.contains("upstream-key"));
        let credentials = serde_json::from_str::<Value>(&credentials_body).unwrap();
        assert_eq!(credentials["total_credentials"], 1);
        let credential = &credentials["credentials"][0];
        assert!(credential["id"].as_str().unwrap().starts_with("cred_"));
        assert_eq!(credential["fingerprint"].as_str().unwrap().len(), 16);
        assert_eq!(credential["state"]["kind"], "available");
        assert_eq!(credential["source"]["source_line"], 1);
        assert!(credential.get("secret").is_none());

        let (events_status, events_body) =
            management_response("/management/events", Some(admin_bearer())).await;
        assert_eq!(events_status, StatusCode::OK);
        assert_eq!(
            serde_json::from_str::<Value>(&events_body).unwrap()["events"]
                .as_array()
                .unwrap()
                .len(),
            0
        );
    }

