    #[tokio::test]
    async fn management_credentials_support_state_filter_and_pagination() {
        let state = test_state_with_keys_api_base_and_event_log_path(
            "upstream-key-1\nupstream-key-2\nupstream-key-3\n",
            "https://example.com/v1",
            None,
        );
        let credential_id = {
            let pool_state = state.channels.get("test").unwrap();
            let pool = pool_state.pool.lock().await;
            pool.credential_snapshots()[0].id.clone()
        };
        expire_credential_response_for_channel(
            &state,
            ManagementEventActor {
                id: "admin".to_string(),
                name: "local-admin".to_string(),
                role: "admin".to_string(),
            },
            "test",
            crate::credentials::CredentialId(credential_id.clone()),
            "manual test".to_string(),
        )
        .await
        .unwrap();

        let app = app(state);
        let expired_response = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri("/management/channels/test/credentials?state=expired&offset=0&limit=1")
                    .header(header::AUTHORIZATION, admin_bearer())
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(expired_response.status(), StatusCode::OK);
        let body = to_bytes(expired_response.into_body(), 4096).await.unwrap();
        let body = serde_json::from_slice::<Value>(&body).unwrap();
        assert_eq!(body["total_credentials"], 3);
        assert_eq!(body["filtered_credentials"], 1);
        assert_eq!(body["offset"], 0);
        assert_eq!(body["limit"], 1);
        assert_eq!(body["state_filter"], "expired");
        assert_eq!(body["credentials"].as_array().unwrap().len(), 1);
        assert_eq!(body["credentials"][0]["id"], credential_id);
        assert_eq!(body["credentials"][0]["state"]["kind"], "expired");

        let available_response = app
            .oneshot(
                Request::builder()
                    .uri("/management/channels/test/credentials?state=available&offset=1&limit=1")
                    .header(header::AUTHORIZATION, admin_bearer())
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(available_response.status(), StatusCode::OK);
        let body = to_bytes(available_response.into_body(), 4096)
            .await
            .unwrap();
        let body = serde_json::from_slice::<Value>(&body).unwrap();
        assert_eq!(body["filtered_credentials"], 2);
        assert_eq!(body["offset"], 1);
        assert_eq!(body["limit"], 1);
        assert_eq!(body["credentials"].as_array().unwrap().len(), 1);
        assert_eq!(body["credentials"][0]["state"]["kind"], "available");
    }

    #[tokio::test]
    async fn management_credentials_show_cooldown_remaining_seconds() {
        let state = test_state_with_keys_api_base_and_event_log_path(
            "upstream-key-1\nupstream-key-2\n",
            "https://example.com/v1",
            None,
        );
        let credential_id = {
            let pool_state = state.channels.get("test").unwrap();
            let mut pool = pool_state.pool.lock().await;
            let credential_id = pool.credential_snapshots()[0].id.clone();
            pool.apply_credential_cooldown_until(
                &crate::credentials::CredentialId(credential_id.clone()),
                Instant::now() + Duration::from_secs(60),
                "upstream cooldown",
            );
            credential_id
        };

        let response = app(state)
            .oneshot(
                Request::builder()
                    .uri("/management/channels/test/credentials?state=cooling_down&limit=1")
                    .header(header::AUTHORIZATION, admin_bearer())
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::OK);
        let body = to_bytes(response.into_body(), 4096).await.unwrap();
        let body = serde_json::from_slice::<Value>(&body).unwrap();
        assert_eq!(body["filtered_credentials"], 1);
        assert_eq!(body["credentials"][0]["id"], credential_id);
        assert_eq!(body["credentials"][0]["state"]["kind"], "cooling_down");
        assert_eq!(
            body["credentials"][0]["state"]["reason"],
            "upstream cooldown"
        );
        let remaining = body["credentials"][0]["state"]["remaining_seconds"]
            .as_u64()
            .unwrap();
        assert!(remaining > 0);
        assert!(remaining <= 60);
    }

