    #[tokio::test]
    async fn management_health_resilience_reports_without_spare_and_cooling_down_counts() {
        let mut config = test_config_with_api_base("https://example.com/v1");
        let management = config.management.as_mut().unwrap();
        management.principals = vec![ManagementPrincipalConfig {
            name: "readonly-fixture".to_string(),
            token: fixture_readonly_management_token(),
            role: ManagementRole::Readonly,
            enabled: true,
        }];
        config.credential_sets = credential_sets_from_files([(
            "test-credentials",
            temp_keys_file("upstream-key-a\nupstream-key-b\n"),
        )]);
        let store_path = temp_sqlite_path("management-health-resilience-counts");
        let repository = SqliteCredentialRepository::open(&store_path).unwrap();
        let state = AppState::new(
            config
                .resolve_with_credential_repository_and_store_path(&repository, Some(store_path))
                .unwrap(),
        )
        .unwrap();
        let credential_id = {
            let channel = state.channels.get("test").unwrap();
            let pool = channel.pool.lock().await;
            pool.credential_snapshots()[0].id.clone()
        };
        {
            let channel = state.channels.get("test").unwrap();
            channel.pool.lock().await.apply_credential_cooldown_until(
                &crate::credentials::CredentialId(credential_id),
                Instant::now() + Duration::from_secs(60),
                "setup cooldown",
            );
            *channel.health.lock().unwrap() = ChannelHealth::CoolingDown {
                until: Instant::now() + Duration::from_secs(60),
                reason: "setup cooldown".to_string(),
            };
        }

        let response = app(state)
            .oneshot(
                Request::builder()
                    .uri("/management/health/resilience")
                    .header(
                        header::AUTHORIZATION,
                        bearer_for(&fixture_readonly_management_token()),
                    )
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::OK);
        let body = to_bytes(response.into_body(), 4096).await.unwrap();
        let health = serde_json::from_slice::<Value>(&body).unwrap();
        assert_eq!(health["status"], "blocked");
        assert_eq!(health["operator_input_alerts"], 1);
        assert_eq!(health["credential_sets_without_spare"], 1);
        assert_eq!(health["channels_cooling_down"], 1);
        assert_eq!(health["response_filter_alerts"], 0);
        assert_eq!(
            health["credential_spare_capacity"]["credential_sets_without_spare"],
            health["credential_sets_without_spare"]
        );
        assert_eq!(
            health["credential_spare_capacity"]["available_credentials"],
            1
        );
        assert_eq!(
            health["credential_spare_capacity"]["cooling_down_credentials"],
            1
        );
        assert_eq!(health["relay_suppression"]["channels_cooling_down"], 1);
        assert_eq!(health["response_filter_alert_summary"]["alerts"], 0);
    }

    #[tokio::test]
    async fn management_credential_set_operations_reports_transition_required() {
        let state = test_state_with_keys(["upstream-key-a", "upstream-key-b"]);
        let credential_id = {
            let channel = state.channels.get("test").unwrap();
            let pool = channel.pool.lock().await;
            pool.credential_snapshots()[0].id.clone()
        };
        {
            let channel = state.channels.get("test").unwrap();
            channel
                .pool
                .lock()
                .await
                .expire_credential_by_id(
                    &crate::credentials::CredentialId(credential_id),
                    "upstream auth invalid",
                )
                .unwrap();
        }

        let response = app(state)
            .oneshot(
                Request::builder()
                    .uri("/management/credential-sets/test-credentials/operations")
                    .header(header::AUTHORIZATION, admin_bearer())
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::OK);
        let body = to_bytes(response.into_body(), 8192).await.unwrap();
        let body = String::from_utf8(body.to_vec()).unwrap();
        assert!(!body.contains("upstream-key"));
        let operations = serde_json::from_str::<Value>(&body).unwrap();
        assert_eq!(operations["credential_set_id"], "test-credentials");
        assert_eq!(operations["status"], "transition_required");
        assert_eq!(operations["serving_mode"], "serving_degraded");
        assert_eq!(operations["accepting_requests"], true);
        assert_eq!(operations["needs_operator_input"], true);
        assert_eq!(operations["required_action"], "import_valid_credentials");
        assert_eq!(operations["credentials"]["total"], 2);
        assert_eq!(operations["credentials"]["available"], 1);
        assert_eq!(
            operations["alerts"][0]["kind"],
            "credential_set_transition_required"
        );
        assert_eq!(operations["alerts"][0]["severity"], "warning");
        assert_eq!(
            operations["alerts"][0]["message"],
            "credential set is serving on a single available credential; import validated replacement credentials"
        );
    }

