        assert_eq!(alerts["operator_input_alerts"], 1);
        assert_eq!(alerts["blocking_alerts"], 0);
        assert_eq!(alerts["alerts"][0]["kind"], "credential_set_probe_unknown");
        assert_eq!(alerts["alerts"][0]["severity"], "warning");
        assert_eq!(alerts["alerts"][0]["resource_id"], "shared-credentials");
