    #[tokio::test]
    async fn management_import_returns_post_import_operations_status() {
        let state = test_state_with_keys(["upstream-key-a", "upstream-key-b"]);
        let credential_id = {
            let channel = state.channels.get("test").unwrap();
            let pool = channel.pool.lock().await;
            pool.credential_snapshots()[0].id.clone()
        };
        {
            let channel = state.channels.get("test").unwrap();
            channel
                .pool
                .lock()
                .await
                .expire_credential_by_id(
                    &crate::credentials::CredentialId(credential_id),
                    "upstream auth invalid",
                )
                .unwrap();
        }

        let before_alerts =
            management_response_json(&app(state.clone()), "/management/alerts").await;
        assert_eq!(before_alerts["total_alerts"], 1);
        assert_eq!(before_alerts["operator_input_alerts"], 1);

        let state_for_import = state.clone();
        let response = app(state_for_import)
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/management/credential-sets/test-credentials/credentials/import")
                    .header(header::AUTHORIZATION, admin_bearer())
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"keys":["upstream-key-c"],"batch_id":"replacement-batch"}"#,
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::OK);
        let body = to_bytes(response.into_body(), 8192).await.unwrap();
        let body = String::from_utf8(body.to_vec()).unwrap();
        assert!(!body.contains("upstream-key"));
        let imported = serde_json::from_str::<Value>(&body).unwrap();
        assert_eq!(imported["imported_credentials"], 1);
        assert_eq!(imported["operations"]["status"], "degraded");
        assert_eq!(imported["operations"]["serving_mode"], "serving");
        assert_eq!(imported["operations"]["accepting_requests"], true);
        assert_eq!(imported["operations"]["needs_operator_input"], false);
        assert_eq!(
            imported["operations"]["required_action"],
            "monitor_or_restore_credentials"
        );
        assert_eq!(imported["operations"]["credentials"]["total"], 3);
        assert_eq!(imported["operations"]["credentials"]["available"], 2);
        assert_eq!(
            imported["operations"]["alerts"][0]["kind"],
            "credential_set_degraded"
        );

        let after_alerts = management_response_json(&app(state), "/management/alerts").await;
        assert_eq!(after_alerts["total_alerts"], 1);
        assert_eq!(after_alerts["info_alerts"], 1);
        assert_eq!(after_alerts["operator_input_alerts"], 0);
        assert_eq!(after_alerts["blocking_alerts"], 0);
        assert_eq!(after_alerts["alerts"][0]["kind"], "credential_set_degraded");
    }

