    #[tokio::test]
    async fn default_channel_without_available_credentials_returns_pool_exhausted() {
        let hits = Arc::new(Mutex::new(0usize));
        let hits_for_handler = hits.clone();
        let upstream = Router::new().route(
            "/v1/chat/completions",
            post(move || {
                let hits = hits_for_handler.clone();
                async move {
                    *hits.lock().await += 1;
                    Json(serde_json::json!({"unexpected": true}))
                }
            }),
        );
        let upstream_base = spawn_upstream(upstream).await;
        let state = test_state_with_api_base(&upstream_base);
        let credential_id = {
            let channel = state.channels.get("test").unwrap();
            let pool = channel.pool.lock().await;
            pool.credential_snapshots()[0].id.clone()
        };
        {
            let channel = state.channels.get("test").unwrap();
            channel
                .pool
                .lock()
                .await
                .disable_credential_by_id(
                    &crate::credentials::CredentialId(credential_id),
                    "operator rotation",
                )
                .unwrap();
        }

        let response = app(state.clone())
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/chat/completions")
                    .header(header::AUTHORIZATION, client_bearer())
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","messages":[{"role":"user","content":"ok"}]}"#,
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(*hits.lock().await, 0);
        assert_eq!(response.status(), StatusCode::SERVICE_UNAVAILABLE);
        let body = to_bytes(response.into_body(), 4096).await.unwrap();
        let value: Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(value["error"]["code"], "credential_pool_exhausted");
    }

