    #[tokio::test]
    async fn routing_telemetry_reports_automatic_credential_expiration() {
        let upstream = Router::new().route(
            "/v1/chat/completions",
            post(|| async {
                (
                    StatusCode::UNAUTHORIZED,
                    Json(serde_json::json!({
                        "error": {
                            "code": "invalid_api_key",
                            "message": "invalid key"
                        }
                    })),
                )
            }),
        );
        let upstream_base = spawn_upstream(upstream).await;
        let state = test_state_with_api_base(&upstream_base);
        let credential_id = {
            let channel = state.channels.get("test").unwrap();
            let pool = channel.pool.lock().await;
            pool.credential_snapshots()[0].id.clone()
        };

        let response = app(state.clone())
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/chat/completions")
                    .header(header::AUTHORIZATION, client_bearer())
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","messages":[{"role":"user","content":"ok"}]}"#,
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::UNAUTHORIZED);

        let telemetry =
            management_response_json(&app(state), "/management/routing-telemetry").await;
        let events = telemetry["events"].as_array().unwrap();
        let transition = events
            .iter()
            .find(|event| event["kind"] == "credential_transition_applied")
            .expect("automatic credential transition telemetry event");
        assert_eq!(transition["channel_id"], "test");
        assert_eq!(transition["credential_id"], credential_id);
        assert_eq!(transition["state"], "expired");
        assert_eq!(transition["reason"], "upstream_auth_invalid");
    }

    #[tokio::test]
    async fn routing_telemetry_does_not_report_rejected_channel_transition_as_applied() {
        let state = test_state();
        let pool_state = state.channels.get("test").unwrap();
        let selected = {
            let mut pool = pool_state.pool.lock().await;
            pool.select().unwrap()
        };
        let stale_generation = pool_state.channel_health_generation.load(Ordering::Acquire);
        let snapshot = RequestSelectionSnapshot {
            request_id: "req_stale_channel_health".to_string(),
            config_generation: pool_state.config_generation,
            channel_health_generation: stale_generation,
            client_token_id: "client_test".to_string(),
            requested_model: Some("gpt-test".to_string()),
            endpoint: crate::provider::EndpointKind::ChatCompletions,
            route_target_index: None,
            channel_id: ChannelId("test".to_string()),
            provider_id: pool_state.provider_id.clone(),
            account_id: pool_state.account_id.clone(),
            provider_kind: ProviderKind::OpenAiCompatible,
            credential_id: selected.credential_id,
            credential_fingerprint: selected.credential_fingerprint,
            classifier_id: "test".to_string(),
            classifier_version: "1".to_string(),
            retry_candidates: Vec::new(),
            body_replayable: true,
            streaming: false,
            partial_output_started: false,
            route_target_available: false,
            effective_deadline: None,
            attempt: 0,
            selection_reason: SelectionReason::DefaultPool,
        };
        assert!(pool_state.apply_automatic_channel_health_transition(
            stale_generation,
            ChannelHealth::Degraded {
                reason: "newer failure".to_string(),
            },
        ));

        transition_observed_upstream_failure(
            &state,
            &pool_state,
            &snapshot,
            ClassifiedFailure {
                kind: FailureKind::ProviderUnavailable,
                primary_scope: FailureScope::Channel,
                retryable: true,
                cooldown: None,
                retry_after_source: None,
                confidence: FailureConfidence::High,
                upstream_status: Some(502),
                upstream_code: Some("upstream_unavailable".to_string()),
                upstream_limit_type: None,
                classifier_id: "test".to_string(),
                classifier_version: "1".to_string(),
                adaptation_rule_id: None,
            },
        )
        .await;

        assert_eq!(
            *pool_state
                .health
                .lock()
                .expect("channel health mutex poisoned"),
            ChannelHealth::Degraded {
                reason: "newer failure".to_string(),
            }
        );
        let telemetry =
            management_response_json(&app(state), "/management/routing-telemetry").await;
        let events = telemetry["events"].as_array().unwrap();
        assert!(events.iter().any(|event| {
            event["kind"] == "upstream_failure_observed"
                && event["request_id"] == "req_stale_channel_health"
        }));
        assert!(!events.iter().any(|event| {
            event["kind"] == "channel_health_transition_applied"
                && event["request_id"] == "req_stale_channel_health"
        }));
        assert!(!events.iter().any(|event| {
            event["kind"] == "transition_applied"
                && event["request_id"] == "req_stale_channel_health"
        }));
    }

