    #[tokio::test]
    async fn automatic_credential_expiration_survives_sqlite_restart() {
        let upstream = Router::new().route(
            "/v1/chat/completions",
            post(|| async {
                (
                    StatusCode::UNAUTHORIZED,
                    Json(serde_json::json!({
                        "error": {
                            "code": "invalid_api_key",
                            "message": "invalid key"
                        }
                    })),
                )
            }),
        );
        let upstream_base = spawn_upstream(upstream).await;
        let store_path = temp_sqlite_path("automatic-expiration-restart");
        let first_state = test_state_with_keys_api_base_event_log_and_store_path(
            "upstream-key\n",
            &upstream_base,
            None,
            store_path.clone(),
        );

        let response = app(first_state)
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/chat/completions")
                    .header(header::AUTHORIZATION, client_bearer())
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","messages":[{"role":"user","content":"ok"}]}"#,
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::UNAUTHORIZED);

        let repository = SqliteCredentialRepository::open(&store_path).unwrap();
        let credential_set_id = CredentialSetId("test-credentials".to_string());
        let mut persisted = Vec::new();
        for _ in 0..50 {
            persisted = repository
                .load_lifecycle_snapshots(&credential_set_id)
                .unwrap();
            if persisted.len() == 1 {
                break;
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
        assert_eq!(persisted.len(), 1);
        assert!(matches!(
            persisted[0].state,
            CredentialLifecycleState::Expired { .. }
        ));

        let restarted_state = test_state_with_keys_api_base_event_log_and_store_path(
            "upstream-key\n",
            &upstream_base,
            None,
            store_path,
        );
        let runtime = management_response_json(&app(restarted_state), "/management/runtime").await;

        assert_eq!(runtime["credentials"]["total"], 1);
        assert_eq!(runtime["credentials"]["available"], 0);
        assert_eq!(runtime["credentials"]["expired"], 1);
        assert_eq!(
            runtime["credential_pool_alerts"][0]["kind"],
            "credential_pool_exhausted"
        );
    }

