        let state = test_state_with_keys_api_base_event_log_and_store_path(
            "upstream-key\n",
            &upstream_base,
            None,
            store_path.clone(),
        );

        let response = app(state.clone())
            .oneshot(
                Request::builder()
                    .uri("/v1/models")
                    .header(header::AUTHORIZATION, client_bearer())
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
