    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn routing_telemetry_lock_contention_does_not_block_proxy_request() {
        let upstream = Router::new().route(
            "/v1/chat/completions",
            post(|| async { Json(serde_json::json!({"id":"ok"})) }),
        );
        let api_base = spawn_upstream(upstream).await;
        let state = test_state_with_api_base(&api_base);
        let telemetry = state.routing_telemetry.clone();
        let (locked_tx, locked_rx) = mpsc::channel();
        let (release_tx, release_rx) = mpsc::channel();
        let holder = std::thread::spawn(move || {
            let _guard = telemetry.lock().expect("routing telemetry mutex poisoned");
            locked_tx.send(()).unwrap();
            release_rx.recv().unwrap();
        });
        locked_rx.recv().unwrap();

        let request = app(state).oneshot(
            Request::builder()
                .method("POST")
                .uri("/v1/chat/completions")
                .header(header::AUTHORIZATION, client_bearer())
                .header(header::CONTENT_TYPE, "application/json")
                .body(Body::from(
                    r#"{"model":"gpt-test","messages":[{"role":"user","content":"ok"}]}"#,
                ))
                .unwrap(),
        );
        let response = tokio::time::timeout(Duration::from_millis(250), request).await;
        release_tx.send(()).unwrap();
        holder.join().unwrap();

        let response = response
            .expect("proxy request should not wait for routing telemetry lock")
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
    }

