    #[tokio::test]
    async fn management_reset_cooldown_clears_only_cooling_down_credentials() {
        let state = test_state_with_api_base("https://example.com/v1");
        let pool_state = state.channels.get("test").unwrap().clone();
        let credential_id = {
            let mut pool = pool_state.pool.lock().await;
            let credential_id = pool.credential_snapshots()[0].id.clone();
            pool.apply_credential_cooldown_until(
                &crate::credentials::CredentialId(credential_id.clone()),
                Instant::now() + Duration::from_secs(60),
                "upstream cooldown",
            );
            credential_id
        };
        let app = app(state.clone());

        let response = app
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(format!(
                        "/management/channels/test/credentials/{credential_id}/reset-cooldown"
                    ))
                    .header(header::AUTHORIZATION, admin_bearer())
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(r#"{"reason":"manual reset"}"#))
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::OK);
        let body = to_bytes(response.into_body(), 4096).await.unwrap();
        let body = serde_json::from_slice::<Value>(&body).unwrap();
        assert_eq!(body["state"]["kind"], "available");
        assert_eq!(state.events.len(), 1);
        let events = state.events.window_blocking(0, 10).1;
        assert_eq!(events[0].kind, "credential_cooldown_cleared");
        let pool = pool_state.pool.lock().await;
        let snapshot = pool
            .credential_snapshot_by_id(&crate::credentials::CredentialId(credential_id))
            .unwrap();
        assert!(matches!(
            snapshot.state,
            crate::credentials::CredentialStateSnapshot::Available
        ));
    }

