    #[tokio::test]
    async fn management_expire_already_expired_is_idempotent_without_event_or_reason_overwrite() {
        let state = test_state_with_api_base("https://example.com/v1");
        let pool_state = state.channels.get("test").unwrap().clone();
        let credential_id = {
            let mut pool = pool_state.pool.lock().await;
            let credential_id = pool.credential_snapshots()[0].id.clone();
            pool.expire_credential_by_id(
                &crate::credentials::CredentialId(credential_id.clone()),
                "existing reason",
            );
            credential_id
        };
        let actor = ManagementEventActor {
            id: "admin".to_string(),
            name: "local-admin".to_string(),
            role: "admin".to_string(),
        };

        let result = expire_credential_response_for_channel(
            &state,
            actor,
            "test",
            crate::credentials::CredentialId(credential_id.clone()),
            "new reason should not overwrite".to_string(),
        )
        .await
        .unwrap();

        assert_eq!(state.events.len(), 0);
        let history = state
            .credential_store
            .load_lifecycle_history(
                CredentialSetId("test-credentials".to_string()),
                crate::credentials::CredentialId(credential_id.clone()),
                0,
                10,
            )
            .await
            .unwrap();
        assert!(
            history.is_empty(),
            "idempotent expire must not create lifecycle history"
        );
        assert_eq!(
            result.state,
            crate::credentials::CredentialStateSnapshot::Expired {
                reason: "existing reason".to_string()
            }
        );
        let pool = pool_state.pool.lock().await;
        let snapshot = pool
            .credential_snapshot_by_id(&crate::credentials::CredentialId(credential_id))
            .unwrap();
        assert_eq!(
            snapshot.state,
            crate::credentials::CredentialStateSnapshot::Expired {
                reason: "existing reason".to_string()
            }
        );
    }

