    #[tokio::test]
    async fn v1_models_returns_compiled_catalog_without_polling_request_body() {
        let api_base = spawn_upstream(Router::new()).await;
        let mut config = test_config_with_api_base(&api_base);
        config.model_routes = HashMap::from([priority_route("gpt-public", ["test"])]);
        let body_polled = Arc::new(AtomicU64::new(0));
        let body_polled_for_stream = body_polled.clone();
        let body_stream = stream::poll_fn(move |_cx| {
            body_polled_for_stream.fetch_add(1, Ordering::SeqCst);
            std::task::Poll::<Option<Result<Bytes, std::convert::Infallible>>>::Pending
        });

        let response = tokio::time::timeout(
            Duration::from_millis(100),
            app(AppState::new(config.resolve().unwrap()).unwrap()).oneshot(
                Request::builder()
                    .method("GET")
                    .uri("/v1/models")
                    .header(header::AUTHORIZATION, client_bearer())
                    .body(Body::from_stream(body_stream))
                    .unwrap(),
            ),
        )
        .await
        .expect("v1 models should return without waiting for request body")
        .unwrap();

        assert_eq!(response.status(), StatusCode::OK);
        let body = to_bytes(response.into_body(), 4096).await.unwrap();
        let value: Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(value["data"][0]["id"], "gpt-public");
        assert_eq!(body_polled.load(Ordering::SeqCst), 0);
    }

