    #[tokio::test]
    async fn forwards_query_string_once() {
        let captured_uri = Arc::new(Mutex::new(None::<String>));
        let captured_uri_for_handler = captured_uri.clone();
        let upstream = Router::new().route(
            "/v1/chat/completions",
            post(move |uri: axum::http::Uri| {
                let captured_uri = captured_uri_for_handler.clone();
                async move {
                    *captured_uri.lock().await = Some(uri.to_string());
                    Json(serde_json::json!({
                        "id": "fixture",
                        "object": "chat.completion",
                        "choices": [
                            {"message": {"role": "assistant", "content": "ok"}}
                        ]
                    }))
                }
            }),
        );
        let api_base = spawn_upstream(upstream).await;

        let response = app(test_state_with_api_base(&api_base))
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/chat/completions?limit=3")
                    .header(header::AUTHORIZATION, client_bearer())
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","messages":[{"role":"user","content":"ok"}]}"#,
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            captured_uri.lock().await.as_deref(),
            Some("/v1/chat/completions?limit=3")
        );
    }

    #[tokio::test]
    async fn openai_compatible_forwarding_uses_upstream_auth() {
        let captured_auth = Arc::new(Mutex::new(None::<String>));
        let captured_x_api_key = Arc::new(Mutex::new(None::<String>));
        let captured_auth_for_handler = captured_auth.clone();
        let captured_x_api_key_for_handler = captured_x_api_key.clone();
        let upstream = Router::new().route(
            "/v1/chat/completions",
            post(move |headers: HeaderMap| {
                let captured_auth = captured_auth_for_handler.clone();
                let captured_x_api_key = captured_x_api_key_for_handler.clone();
                async move {
                    *captured_auth.lock().await = headers
                        .get(header::AUTHORIZATION)
                        .and_then(|value| value.to_str().ok())
                        .map(ToOwned::to_owned);
                    *captured_x_api_key.lock().await = headers
                        .get("x-api-key")
                        .and_then(|value| value.to_str().ok())
                        .map(ToOwned::to_owned);
                    Json(serde_json::json!({
                        "id": "fixture",
                        "object": "chat.completion",
                        "choices": [
                            {"message": {"role": "assistant", "content": "ok"}}
                        ]
                    }))
                    .into_response()
                }
            }),
        );
        let api_base = spawn_upstream(upstream).await;

        let response = app(test_state_with_api_base(&api_base))
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/chat/completions")
                    .header(header::AUTHORIZATION, client_bearer())
                    .header("x-api-key", "client-side-secret")
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","messages":[{"role":"user","content":"ok"}]}"#,
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::OK);
        let body = to_bytes(response.into_body(), 4096).await.unwrap();
        let value: Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(value["choices"][0]["message"]["content"], "ok");
        assert_eq!(
            captured_auth.lock().await.as_deref(),
            Some("Bearer upstream-key")
        );
        assert_eq!(captured_x_api_key.lock().await.as_deref(), None);
    }

