    #[tokio::test]
    async fn priority_weighted_sticky_model_route_distributes_first_attempts() {
        let hits_a = Arc::new(Mutex::new(0usize));
        let hits_a_for_handler = hits_a.clone();
        let upstream_a = Router::new().route(
            "/v1/chat/completions",
            post(move || {
                let hits_a = hits_a_for_handler.clone();
                async move {
                    *hits_a.lock().await += 1;
                    Json(serde_json::json!({
                        "id": "fixture-a",
                        "object": "chat.completion",
                        "choices": [
                            {"message": {"role": "assistant", "content": "a"}}
                        ]
                    }))
                }
            }),
        );
        let base_a = spawn_upstream(upstream_a).await;

        let hits_b = Arc::new(Mutex::new(0usize));
        let hits_b_for_handler = hits_b.clone();
        let upstream_b = Router::new().route(
            "/v1/chat/completions",
            post(move || {
                let hits_b = hits_b_for_handler.clone();
                async move {
                    *hits_b.lock().await += 1;
                    Json(serde_json::json!({
                        "id": "fixture-b",
                        "object": "chat.completion",
                        "choices": [
                            {"message": {"role": "assistant", "content": "b"}}
                        ]
                    }))
                }
            }),
        );
        let base_b = spawn_upstream(upstream_b).await;

        let mut pools = HashMap::new();
        let mut credential_sets = HashMap::new();
        for (name, api_base, key) in [("a", base_a, "a-key"), ("b", base_b, "b-key")] {
            let credential_set = format!("{name}-credentials");
            credential_sets.insert(
                credential_set.clone(),
                CredentialSetConfig {
                    keys_file: temp_keys_file(&format!("{key}\n")),
                },
            );
            pools.insert(
                name.to_string(),
                PoolConfig {
                    enabled: true,
                    account: None,
                    policy_profile: None,
                    routing_profile: None,
                    provider_kind: ProviderKind::OpenAiCompatible,
                    api_base,
                    credential_set,
                    auth_header: "authorization".to_string(),
                    auth_prefix: "Bearer ".to_string(),
                    error_rules: ErrorRulesConfig::default(),
                },
            );
        }

        let state = AppState::new(
            AppConfig {
                listen: "127.0.0.1:0".parse().unwrap(),
                client_tokens: vec![ClientTokenConfig {
                    name: "test-client".to_string(),
                    token: fixture_client_token(),
                    enabled: true,
                    allowed_model_groups: Vec::new(),
                    allowed_channels: Vec::new(),
                }],
                management: Some(ManagementConfig {
                    admin_token: fixture_admin_token(),
                    ip_allowlist: None,
                    principals: Vec::new(),
                    event_log_path: None,
                    event_window_capacity: None,
                }),
                max_request_body_bytes: 1024 * 1024,
                max_model_catalog_body_bytes: 512 * 1024,
                max_error_body_bytes: 1024,
                timeouts: TimeoutConfig::default(),
                routing: crate::config::RoutingConfig::default(),
                default_pool: Some("a".to_string()),
                providers: HashMap::new(),
                accounts: HashMap::new(),
                credential_sets,
                model_routes: HashMap::from([(
                    "gpt-route".to_string(),
                    crate::config::ModelRouteConfig {
                        strategy: Some("priority_weighted_sticky".to_string()),
                        targets: vec![
                            crate::config::ModelRouteTargetConfig {
                                channel: "a".to_string(),
                                upstream_model: None,
                                priority: 10,
                                weight: 1,
                                enabled: true,
                            },
                            crate::config::ModelRouteTargetConfig {
                                channel: "b".to_string(),
                                upstream_model: None,
                                priority: 10,
                                weight: 1,
                                enabled: true,
                            },
                        ],
                    },
                )]),
                policy_profiles: HashMap::new(),
                default_routing_profile: Some("default-routing".to_string()),
                routing_profiles: std::collections::HashMap::from([
                    (
                        "default-routing".to_string(),
                        crate::config::RoutingProfileConfig {
                            key_selection:
                                crate::config::KeySelectionStrategyConfig::StickyUntilFailure,
                            default_credential_cooldown_seconds: 20,
                            same_request_credential_retry:
                                crate::config::SameRequestCredentialRetryConfig {
                                    enabled: false,
                                    max_retries: 0,
                                },
                            route_target_retry: crate::config::RouteTargetRetryConfig {
                                enabled: true,
                            },
                        },
                    ),
                    (
                        "retry-routing".to_string(),
                        crate::config::RoutingProfileConfig {
                            key_selection:
                                crate::config::KeySelectionStrategyConfig::StickyUntilFailure,
                            default_credential_cooldown_seconds: 20,
                            same_request_credential_retry:
                                crate::config::SameRequestCredentialRetryConfig {
                                    enabled: true,
                                    max_retries: 2,
                                },
                            route_target_retry: crate::config::RouteTargetRetryConfig {
                                enabled: true,
                            },
                        },
                    ),
                ]),
                pools,
            }
            .resolve()
            .unwrap(),
        )
        .unwrap();

        for index in 0..32 {
            let response = app(state.clone())
                .oneshot(
                    Request::builder()
                        .method("POST")
                        .uri("/v1/chat/completions")
                        .header(header::AUTHORIZATION, client_bearer())
                        .header(header::CONTENT_TYPE, "application/json")
                        .body(Body::from(format!(
                            r#"{{"model":"gpt-route","messages":[{{"role":"user","content":"{index}"}}]}}"#
                        )))
                        .unwrap(),
                )
                .await
                .unwrap();

            assert_eq!(response.status(), StatusCode::OK);
        }

        assert!(*hits_a.lock().await > 0);
        assert!(*hits_b.lock().await > 0);
    }

