    #[tokio::test]
    async fn channel_failure_transition_does_not_override_manual_disabled_state() {
        let (upstream_hit_tx, upstream_hit_rx) = oneshot::channel::<()>();
        let upstream_hit_tx = Arc::new(Mutex::new(Some(upstream_hit_tx)));
        let (release_tx, release_rx) = oneshot::channel::<()>();
        let release_rx = Arc::new(Mutex::new(Some(release_rx)));
        let upstream = Router::new().route(
            "/v1/chat/completions",
            post(move || {
                let upstream_hit_tx = upstream_hit_tx.clone();
                let release_rx = release_rx.clone();
                async move {
                    if let Some(tx) = upstream_hit_tx.lock().await.take() {
                        let _ = tx.send(());
                    }
                    if let Some(rx) = release_rx.lock().await.take() {
                        let _ = rx.await;
                    }
                    (
                        StatusCode::BAD_GATEWAY,
                        Json(serde_json::json!({
                            "error": {
                                "code": "upstream_unavailable",
                                "message": "provider unavailable"
                            }
                        })),
                    )
                }
            }),
        );
        let api_base = spawn_upstream(upstream).await;
        let state = test_state_with_api_base(&api_base);
        let request = app(state.clone()).oneshot(
            Request::builder()
                .method("POST")
                .uri("/v1/chat/completions")
                .header(header::AUTHORIZATION, client_bearer())
                .header(header::CONTENT_TYPE, "application/json")
                .body(Body::from(
                    r#"{"model":"gpt-test","messages":[{"role":"user","content":"ok"}]}"#,
                ))
                .unwrap(),
        );
        let request_task = tokio::spawn(async move { request.await.unwrap() });

        upstream_hit_rx.await.unwrap();
        *state.channels.get("test").unwrap().health.lock().unwrap() = ChannelHealth::Disabled {
            reason: "manual stop".to_string(),
        };
        let _ = release_tx.send(());
        let response = request_task.await.unwrap();

        assert_eq!(response.status(), StatusCode::BAD_GATEWAY);
        assert_eq!(
            *state.channels.get("test").unwrap().health.lock().unwrap(),
            ChannelHealth::Disabled {
                reason: "manual stop".to_string()
            }
        );
    }

