    #[tokio::test]
    async fn upstream_retry_after_header_controls_credential_cooldown() {
        let upstream = Router::new().route(
            "/v1/chat/completions",
            post(|| async {
                (
                    StatusCode::TOO_MANY_REQUESTS,
                    [(header::RETRY_AFTER, "1")],
                    Json(serde_json::json!({
                        "error": {
                            "code": "rate_limit_exceeded",
                            "message": "slow down"
                        }
                    })),
                )
            }),
        );
        let api_base = spawn_upstream(upstream).await;
        let state = test_state_with_keys_api_base_and_event_log_path(
            "upstream-key-1\nupstream-key-2\n",
            &api_base,
            None,
        );
        let before_generation = state
            .channels
            .get("test")
            .unwrap()
            .selector_generation
            .load(Ordering::Acquire);

        let response = app(state.clone())
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/chat/completions")
                    .header(header::AUTHORIZATION, client_bearer())
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","messages":[{"role":"user","content":"ok"}]}"#,
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::TOO_MANY_REQUESTS);

        let channel = state.channels.get("test").unwrap();
        let pool = channel.pool.lock().await;
        let snapshot = pool.snapshot();
        assert_eq!(snapshot.cooling_down_credentials, 1);
        drop(pool);
        let after_generation = state
            .channels
            .get("test")
            .unwrap()
            .selector_generation
            .load(Ordering::Acquire);
        assert_eq!(after_generation, before_generation + 1);
    }

