    #[tokio::test]
    async fn provider_unavailable_marks_channel_degraded_without_mutating_credentials() {
        let upstream = Router::new().route(
            "/v1/chat/completions",
            post(|| async {
                (
                    StatusCode::BAD_GATEWAY,
                    Json(serde_json::json!({
                        "error": {
                            "code": "upstream_unavailable",
                            "message": "provider unavailable"
                        }
                    })),
                )
            }),
        );
        let api_base = spawn_upstream(upstream).await;
        let state = test_state_with_keys_api_base_and_event_log_path(
            "upstream-key-1\nupstream-key-2\n",
            &api_base,
            None,
        );

        let response = app(state.clone())
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/chat/completions")
                    .header(header::AUTHORIZATION, client_bearer())
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","messages":[{"role":"user","content":"ok"}]}"#,
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::BAD_GATEWAY);

        let channel = state.channels.get("test").unwrap();
        let pool = channel.pool.lock().await;
        let snapshot = pool.snapshot();
        assert_eq!(snapshot.cooling_down_credentials, 0);
        assert_eq!(snapshot.expired_credentials, 0);
        drop(pool);

        let channel = pool_status_for_channel(&state, "test").await.unwrap();
        let value = serde_json::to_value(channel).unwrap();
        assert_eq!(value["health"]["kind"], "degraded");
        assert_eq!(value["health"]["reason"], "upstream provider unavailable");

        let telemetry =
            management_response_json(&app(state), "/management/routing-telemetry").await;
        let transition = telemetry["events"]
            .as_array()
            .unwrap()
            .iter()
            .find(|event| event["kind"] == "channel_health_transition_applied")
            .expect("channel health transition telemetry event");
        assert_eq!(transition["channel_id"], "test");
        assert_eq!(transition["state"], "degraded");
        assert_eq!(transition["reason"], "upstream_provider_unavailable");
    }

    #[tokio::test]
    async fn response_filter_redacts_success_json_body() {
        let upstream = Router::new().route(
            "/v1/chat/completions",
            post(|| async {
                Json(serde_json::json!({
                    "id": "fixture",
                    "object": "chat.completion",
                    "choices": [
                        {"message": {"role": "assistant", "content": "unsafe-marker"}}
                    ]
                }))
            }),
        );
        let api_base = spawn_upstream(upstream).await;
        let state = test_state_with_response_filter(
            &api_base,
            crate::config::ResponseFilterConfig {
                enabled: true,
                replacement: Some("[filtered]".to_string()),
                event_window_capacity: None,
                alert_window_seconds: None,
                rules: vec![crate::config::ResponseFilterRuleConfig {
                    id: "marker".to_string(),
                    enabled: true,
                    kind: crate::config::ResponseFilterRuleKindConfig::Literal,
                    action: crate::config::ResponseFilterActionConfig::Redact,
                    case_sensitive: false,
                    value: Some("unsafe-marker".to_string()),
                    pattern: None,
                }],
            },
        );

        let response = app(state.clone())
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/chat/completions")
                    .header(header::AUTHORIZATION, client_bearer())
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","messages":[{"role":"user","content":"ok"}]}"#,
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::OK);
        let body = to_bytes(response.into_body(), 4096).await.unwrap();
        let value: Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(value["choices"][0]["message"]["content"], "[filtered]");

        let filter_events =
            management_response_json(&app(state.clone()), "/management/response-filter-events")
                .await;
        let events = filter_events["events"].as_array().unwrap();
        assert_eq!(events.len(), 1);
        assert!(events[0]["request_id"]
            .as_str()
            .unwrap()
            .starts_with("req_"));
        assert_eq!(events[0]["channel_id"], "test");
        assert_eq!(events[0]["public_model"], "gpt-test");
        assert_eq!(events[0]["rule_id"], "marker");
        assert_eq!(events[0]["action"], "redact");
        assert_eq!(events[0]["content_kind"], "json");
        assert_eq!(events[0]["reason_code"], "rule_matched");
        assert_eq!(events[0]["outcome"], "redacted");
        assert_eq!(events[0]["body_committed"], true);
        let serialized_filter_events = serde_json::to_string(&filter_events).unwrap();
        assert!(!serialized_filter_events.contains("unsafe-marker"));
        assert!(!serialized_filter_events.contains("response_body"));
        assert!(!serialized_filter_events.contains("request_body"));

        let telemetry =
            management_response_json(&app(state.clone()), "/management/routing-telemetry").await;
        let telemetry_events = telemetry["events"].as_array().unwrap();
        assert_eq!(telemetry_events.len(), 1);
        assert_eq!(telemetry_events[0]["kind"], "route_selected");

        let channel = state.channels.get("test").unwrap();
        let pool = channel.pool.lock().await;
        let snapshot = pool.snapshot();
        assert_eq!(snapshot.cooling_down_credentials, 0);
        assert_eq!(snapshot.expired_credentials, 0);
    }

