    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn generic_named_pool_streams_request_body_without_full_buffering() {
        let (first_chunk_tx, first_chunk_rx) = oneshot::channel::<Bytes>();
        let first_chunk_tx = Arc::new(Mutex::new(Some(first_chunk_tx)));
        let upstream = Router::new().route(
            "/v1/upload",
            post(move |body: Body| {
                let first_chunk_tx = first_chunk_tx.clone();
                async move {
                    let mut body_stream = body.into_data_stream();
                    if let Some(Ok(chunk)) = body_stream.next().await {
                        if let Some(tx) = first_chunk_tx.lock().await.take() {
                            let _ = tx.send(chunk);
                        }
                    }
                    Json(serde_json::json!({"ok": true}))
                }
            }),
        );
        let api_base = spawn_upstream(upstream).await;
        let keys_file = temp_keys_file("generic-key\n");
        let state = AppState::new(
            AppConfig {
                listen: "127.0.0.1:0".parse().unwrap(),
                client_tokens: vec![ClientTokenConfig {
                    name: "test-client".to_string(),
                    token: fixture_client_token(),
                    enabled: true,
                    allowed_model_groups: Vec::new(),
                    allowed_channels: Vec::new(),
                }],
                management: Some(ManagementConfig {
                    admin_token: fixture_admin_token(),
                    ip_allowlist: None,
                    principals: Vec::new(),
                    event_log_path: None,
                    event_window_capacity: None,
                }),
                max_request_body_bytes: 1024 * 1024,
                max_model_catalog_body_bytes: 512 * 1024,
                max_error_body_bytes: 1024,
                timeouts: TimeoutConfig::default(),
                routing: crate::config::RoutingConfig::default(),
                default_pool: Some("generic".to_string()),
                providers: HashMap::new(),
                accounts: HashMap::new(),
                credential_sets: credential_sets_from_files([("generic-credentials", keys_file)]),
                model_routes: HashMap::new(),
                policy_profiles: HashMap::new(),
                default_routing_profile: Some("default-routing".to_string()),
                routing_profiles: std::collections::HashMap::from([(
                    "default-routing".to_string(),
                    crate::config::RoutingProfileConfig {
                        key_selection:
                            crate::config::KeySelectionStrategyConfig::StickyUntilFailure,
                        default_credential_cooldown_seconds: 20,
                        same_request_credential_retry:
                            crate::config::SameRequestCredentialRetryConfig {
                                enabled: false,
                                max_retries: 0,
                            },
                        route_target_retry: crate::config::RouteTargetRetryConfig { enabled: true },
                    },
                )]),
                pools: HashMap::from([(
                    "generic".to_string(),
                    PoolConfig {
                        enabled: true,
                        account: None,
                        policy_profile: None,
                        routing_profile: None,
                        provider_kind: ProviderKind::GenericHttp,
                        api_base,
                        credential_set: "generic-credentials".to_string(),
                        auth_header: "authorization".to_string(),
                        auth_prefix: "Bearer ".to_string(),
                        error_rules: ErrorRulesConfig::default(),
                    },
                )]),
            }
            .resolve()
            .unwrap(),
        )
        .unwrap();

        let (release_second_tx, release_second_rx) = oneshot::channel::<()>();
        let body_stream =
            stream::once(async { Ok::<Bytes, std::io::Error>(Bytes::from_static(b"first")) })
                .chain(stream::once(async move {
                    let _ = release_second_rx.await;
                    Ok::<Bytes, std::io::Error>(Bytes::from_static(b"second"))
                }));
        let request = app(state).oneshot(
            Request::builder()
                .method("POST")
                .uri("/pools/generic/upload")
                .header(header::AUTHORIZATION, client_bearer())
                .body(Body::from_stream(body_stream))
                .unwrap(),
        );
        let request_task = tokio::spawn(async move { request.await.unwrap() });

        let first_chunk = tokio::time::timeout(Duration::from_millis(250), first_chunk_rx)
            .await
            .expect("generic proxy should forward the first request chunk before full body EOF")
            .expect("upstream should report first chunk");
        assert_eq!(&first_chunk[..], b"first");

        let _ = release_second_tx.send(());
        let response = tokio::time::timeout(Duration::from_secs(2), request_task)
            .await
            .expect("generic request should finish")
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
    }

