    #[tokio::test]
    async fn response_filter_does_not_buffer_unbounded_non_event_stream() {
        let upstream = Router::new().route(
            "/v1/chat/completions",
            post(|| async {
                let body_stream = stream::unfold(0, |state| async move {
                    match state {
                        0 => Some((
                            Ok::<Bytes, std::io::Error>(Bytes::from(vec![b'a'; 9000])),
                            1,
                        )),
                        1 => {
                            tokio::time::sleep(Duration::from_millis(300)).await;
                            Some((Ok(Bytes::from_static(b"\n\n")), 2))
                        }
                        _ => None,
                    }
                });
                Response::builder()
                    .status(StatusCode::OK)
                    .header(header::CONTENT_TYPE, "text/event-stream")
                    .body(Body::from_stream(body_stream))
                    .unwrap()
            }),
        );
        let api_base = spawn_upstream(upstream).await;
        let state = test_state_with_response_filter(
            &api_base,
            crate::config::ResponseFilterConfig {
                enabled: true,
                replacement: Some("[filtered]".to_string()),
                event_window_capacity: None,
                alert_window_seconds: None,
                rules: vec![crate::config::ResponseFilterRuleConfig {
                    id: "marker".to_string(),
                    enabled: true,
                    kind: crate::config::ResponseFilterRuleKindConfig::Literal,
                    action: crate::config::ResponseFilterActionConfig::Redact,
                    case_sensitive: false,
                    value: Some("unsafe-marker".to_string()),
                    pattern: None,
                }],
            },
        );

        let response = app(state)
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/v1/chat/completions")
                    .header(header::AUTHORIZATION, client_bearer())
                    .header(header::CONTENT_TYPE, "application/json")
                    .body(Body::from(
                        r#"{"model":"gpt-test","messages":[{"role":"user","content":"ok"}],"stream":true}"#,
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::OK);
        let mut response_stream = response.into_body().into_data_stream();
        let body_result =
            tokio::time::timeout(Duration::from_millis(250), response_stream.next()).await;
        assert!(
            matches!(body_result, Ok(Some(Ok(_)))),
            "bounded filter should release enough bytes before waiting for the delayed event terminator"
        );
    }
